window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["4630664"]={"book":{"id":4630664,"title":"你的知识需要管理","author":"田志刚","translator":"","publisher":"辽宁科学技术出版社","pubdate":"2010-3","isbn":"9787538162509","tags":["知识管理","个人管理","个人知识管理","学习","自我管理","管理","思维","田志刚"],"memCount":15},"np":1,"pb":[16],"idx":[{"i":9400,"t":"【拆解主题1】管理人脉信息，搞好人际关系，成为受欢迎的人","l":"TF1-1","c":"赖秋燕（Aimee）","g":1,"p":1},{"i":5670,"t":"识别并使用需要掌握的知识","l":"TF2-4","c":"唐思","g":1,"p":1},{"i":2879,"t":"雅美蝶莉拆书","l":"TF1-1","c":"野狸野狸","g":1,"p":1},{"i":2616,"t":"如何评判对知识的掌握程度及如何更好地调整完善自己的知识体系","l":"TF1-1","c":"胡奇伟","g":1,"p":1},{"i":2407,"t":"学习和提升的方法","l":"TF1-2","c":"grace","g":0,"p":1},{"i":2125,"t":"找到自己的共享之道","l":"TF2-1","c":"daisy_莼","g":1,"p":1},{"i":1766,"t":"如何保存“人”","l":"TF1-2","c":"daisy_莼","g":1,"p":1},{"i":1692,"t":"提升自我知识价值","l":"TF1-2","c":"勤息","g":0,"p":1},{"i":1691,"t":"如何更好的交朋友","l":"TF1-1","c":"勤息","g":0,"p":1},{"i":1625,"t":"碎片化知识的整理","l":"TF2-4","c":"王锦康","g":1,"p":1},{"i":1624,"t":"如何分析知识共享的对象","l":"TF2-3","c":"王锦康","g":1,"p":1},{"i":1387,"t":"让你更加了解自己","l":"TF1-2","c":"郭彦超","g":1,"p":1},{"i":1188,"t":"个人知识管理","l":"TF2-2","c":"王锦康","g":1,"p":1},{"i":1133,"t":"《你的知识需要管理》拆书活动","l":"TF3-3","c":"张然","g":1,"p":1},{"i":419,"t":"如何高效学习","l":"TF1-1","c":"公子","g":1,"p":1},{"i":319,"t":"一个小方法，让你更加了解自己","l":"TF1-2","c":"郭彦超","g":1,"p":1}],"ms":[{"id":9400,"topic":"【拆解主题1】管理人脉信息，搞好人际关系，成为受欢迎的人","learn_goal":"管理人脉信息，搞好人际关系，成为受欢迎的人","remark":"个人发展越来越依赖于个人竞争力，拥有优质的人脉关系（资源），更利于提升竞争力。\r\n人脉保存是知识管理重要的一部分。\r\n有句老话：“贵人相助”，但谁会是我们的贵人呢？无人知道，从人际资本角度来看，每个人都有自己的优势，特长和资源，在每个人熟悉的领域里，每个人都是专家，这样看来，每个人都有可能成为我们的贵人，在关键时刻可以提携或帮我们一把。\r\n想知道如何留住“贵人”吗? 一起来学习Get新技能吧～","level":"TF1-1","duration":15,"status":29,"type":0,"chaishujia":{"username":"赖秋燕（Aimee）","city":"深圳"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"书友们大家晚上好！我叫赖秋燕，来自广东阳江。\r\n用三个标签做自我介绍。\r\n标签1：新晋全职宝妈一枚。\r\n标签2：早起星人，每天5点起床读书。\r\n标签3：正在拆书打怪升级中的拆书家，这是我的新标签，我很喜欢，希望以最快的时间成为一名真正的拆书家。\r\n我的介绍就到这里，谢谢。\r\n拆书帮是一个非营利性学习爱好者组织（社群），以RIA拆书法为学习方法论，在很多城市中有分舵，便于学习与交流。大家现在参加的就是其中一个分舵，智荟分舵。\r\n拆书，是拆书帮拥有知识产权的专有名词，是受法律保护的。主要以RIA便签法将书中知识拆为已用。\r\nR代表原文知识，也就是拆页内容，\r\nI 用自己的话重述原文知识，\r\nA 分为A1和A2。\r\nA1自己过去相关的经验，成功失败的都可以，\r\nA2规划自己未来的应用。以这种方法把书中知识拆解重组并应用，最终变成自己的。\r\n而拆书家则是拆书帮的会员，能通过RIA便签法来引导和促进他人学习。\r\n接下来，我就给大家分享我的四个便签：\r\n请大家用2分钟快速阅读片段，阅读完的伙伴请举手示意我。\r\n原文拆页选自《你的知识需要管理》 第三章第五节———对“人”的保存","ratings_count":1,"texts":[{"id":13203,"quote":"\u003cp>R原文拆页：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>第三章：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如何保“人”\u003c/strong>\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>我认识的一位咨询和培训顾问的案例：保存“人”，保存人的什么？\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>基本情况：姓名、服务机构、部门、职位、电话（固定、移动）、传真、网址、博客地址、\u003c/p>\u003cp>即时通讯工具（MSN、QQ、Skype、飞信、Gtalk等）。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>背景情况：在沟通中获得的背景信息，例如老家在哪里的，什么学校毕业，什么专业，\u003c/p>\u003cp>有什么爱好，配偶是做什么的，是否有小孩，小孩情况，父母情况等。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>联系过程：你们讨论的事情、他们正在做或者准备做的项目、他最近的心情、说过什么、想过什么、\u003c/p>\u003cp>写过什么、讨论过什么\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>如果你能够保存这些信息，那么你跟这个人的交流和沟通的效率会明显提高，\u003c/p>\u003cp>你们建立关系的可能性会大大提高。而且，保存这些信息并不难，因为你们每一次的见面都会沟通、\u003c/p>\u003cp>交流、分享，哪怕是通过喝酒也可以发现一个人的特点、价值观，只需要你用心去做，\u003c/p>\u003cp>同时及时的整理、归纳也很重要，否则时间一久就会忘掉。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003cp>\u003cstrong>作为一个社会人，无论是学生，职场中人，还是企业老总，每天都会接触许许多多的人，认识和收集到很多的人脉信息，但你是否能够做到“结识新朋友，不忘老朋友”呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>假如有人在微信上无数次地问你同一个问题（例如你是做什么业务的，你住在哪？），你会是什么感受？你还会想和对方沟通下去吗？\u003c/strong>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>假如有个只交流过一两次的朋友突然在你过生日那天给你打一个电话祝福你，你又会是什么感受？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>可能我们手机通讯录里，名片里有几十或上百个人的联系资料，但这里面有多少是见过一次就不再见，有多少是交流过但你却不记得对方是做什么的？有多少是你需要帮忙时可以去求助的？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>有句老话：“贵人相助”，但谁会是我们的贵人呢？无人知道，从人际资本角度来看，每个人都有自己的优势，特长和资源，在每个人熟悉的领域里，每个人都是专家，这样看来，每个人都有可能成为我们的贵人，在关键时刻可以提携或帮我们一把。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>成功学经常引用的一句话：“成功＝\u003c/strong>\u003cstrong>20\u003c/strong>\u003cstrong>％的知识＋\u003c/strong>\u003cstrong>80\u003c/strong>\u003cstrong>％的人脉”，好莱坞也流行着一句话：“一个人能否成功，不在于你知道什么（\u003c/strong>\u003cstrong>what you know\u003c/strong>\u003cstrong>），而是在于你认识谁（\u003c/strong>\u003cstrong>whom you know\u003c/strong>\u003cstrong>）”。虽然不是绝对，但这些话在很大程度上印证了保存“人”（人脉信息）的重要性。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>那我们应该如何详细管理人脉信息搞好人际关系，成为受欢迎的人呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步：了解对方基本情况\u003c/strong>\u003c/p>\u003cp>\u003cstrong>包括姓名、公司、部门、职位、电话（固定、移动）、传真、网址、博客地址、即时通讯工具等基本信息\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步：掌握实际背景情况\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在双方沟通中，想办法在自然不尴尬的聊天当中掌握对方的背景情况，包括籍贯，毕业学校，专业，爱好，婚否\u003c/strong>\u003cstrong>/\u003c/strong>\u003cstrong>配偶做什么，家庭情况等。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步：记录当时联系过程\u003c/strong>\u003c/p>\u003cp>\u003cstrong>在认识时讨论过的事情，他做的项目，说过，想过，写过，讨论过什么等等的过程。\u003c/strong>\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>17年5月，我在深圳某酒店参加了一场2天1夜的营销培训，有几十个人参加，各行各业的都有，有企业老板，职场精艺，自由职业者等。\u003c/p>\u003cp>跟我分在一组的，一共有6个人，大家相互交换名片，介绍彼此，来自五湖四海，有的做业务，有的还是海归回国做培训，有的是律师，当时认识大家可开心涨见识了，一下子多了这么多利害优秀的同学们，以后有什么都可以相互帮忙了。\u003c/p>\u003cp>但是培训结束之后，没多久，这些同学们都“失联”了，有的名片还在，有的已经不见，也想不起来他是做什么叫什么名字了……\u003c/p>\u003cp>学了人脉信息保存我才知道，原来是自己只了解了对方的基本信息，姓名电话这些，没有刻意地去做好第二和第三步，没有在当天就做好人脉信息的管理（记录），才错失了一些可以建立起关系的优质人脉。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>\u003cstrong>目标：规划了对知识的具体运用，听起来够清晰、能执行\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>从今天开始，花1个月时间，做好一份详细的人脉清单表。\u003c/p>\u003cp>以后认识新的朋友时，也运用这三步去收集管理人脉信息，并做好详细记录。\u003c/p>\u003cp>行动：\u003c/p>\u003cp>安排在每天晚上8～9点整理，按照上面的三个步骤，每次梳理3～5个联系人，把最新记录详细登记进表格，30天内完成全部联系人的管理保存更新工作，做好一份详细的人脉清单表。\u003c/p>\u003cp>1.了解对方基本情况。\u003c/p>\u003cp>检查通讯录，如果只有电话和名字，就想办法再和对方再次建立沟通，把地址和现在职位情况等了解到并作好记录。\u003c/p>\u003cp>2.掌握实际背景情况。\u003c/p>\u003cp>检查通讯录，背景情况是否已掌握，若没有，再次沟通联系，了解对方现在最新状态，补全信息。\u003c/p>\u003cp>3.记录当时联系过程。\u003c/p>\u003cp>回忆当时认识对方时，发生过什么过程，产生过什么合作等，现在将来可以如何继续建立连接关系。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1575534535000,"updated_at":1575534535000,"ria":true},{"id":5670,"topic":"识别并使用需要掌握的知识","learn_goal":"能够更有效率获得知识以及掌握学习模型提升学习效果","remark":"","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"唐思","city":"武汉"},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;开场：大家好，我是七七，来自沌口，我的目标是成为三级拆书家。\r\n【学习目标】大家跟随我完成本次RIA现场学习后，能使用”价值/时间“的判断方法，更有效率获得知识以及掌握学习模型提升学习效果。开始之前，先给大家进行一个分组。\r\n【图书介绍】\r\nF：今天给大家介绍的这本书是《你的知识需要管理》，是知名的知识管理专家田志刚，针对知识管理入门所写的一本介绍个人知识管理的书。本书通过案例、问答等生动的形式深入浅出地阐述系统打造个人知识力的理念、方法、工具与技巧，使读者能够掌握提升个人竞争力、实现自我价值的流程和路径，是一本贡献给知识工作者的佳作。\r\nA：田志刚是个人知识管理领域的专家，对这个方面的了解非常的深入，相较于其他知识管理的理论性，这本书的内容既做到深度剖析，又做到浅显易懂，是中国本土较早的一本系统讲述个人知识管理的书籍，也是很多后来做知识管理的大咖经常会提到的入门书籍。\r\nB1：在这么一个知识爆炸的时代，许多人都会面临着知识焦虑，作者把个人知识管理的过程分成了5步：学习知识→保存知识→共享知识→使用知识→创新知识。 我相信大多数的没有接触过个人知识管理的人，在读过这本书之后，一定可以对知识管理产生一个完整的印象。\r\nB2：如果你会因为面临海量知识而不知所错，会因为不知道学习的方法而焦虑，报了很多班，听了很多课，却依然处理不好生活和工作，那么本次拆页的片段可以很好的帮助你去提高知识的获取效率，并能更好的系统化了解某一个知识领域。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":8860,"quote":"\u003cp>片段一\u003c/p>\u003cp>在年轻的时候，总觉得有大把的青春，可你总有一天会感觉到时间对自己很吝啬，时间如此短暂，所以要考虑如何更有效率的去获取知识。\u003c/p>\u003cp>如何才能提高价值时间的值，如图所示：\u003c/p>\u003cp>通过这个简单的四象限图，我们可以看出：\u003c/p>\u003cp>1.是那种花费时间比较长，获得价值较高的活动；\u003c/p>\u003cp>2.是那种花费时间比较短，获得价值较高的活动；\u003c/p>\u003cp>3.是那种花费时间比较短，获得价值较低的活动；\u003c/p>\u003cp>4.是那种花费时间比较长，获得价值较低的活动。\u003c/p>\u003cp>第4象限花费的时间长，但收益低，要抛弃需要很长时间，而收益很低的学习活动，坚决不能参加。\u003c/p>\u003cp>第2象限表示花费时间短，对个人价值较高，这肯定是最好的选择，我们在学习时应该将时间分配在这样的活动上，第1象限学习所要花费的时间和预期价值都比较高，这时候你就应该斟酌一下是否有花费时间较少，也能达到同等价值的替代方案，如果你比较重视学位，而这个学位的价值对你可能比较高，例如你的单位涨工资、分房子、升职等，与学位有关，如果你只是需要这个学位，而不是想得到知识，那么你就没有必要去上那些全日制班，而要去找花费时间少，又能替代学位的替代方法，例如周末班、月末班等函授班，对于第3象限的情况，花费时间较少而预期价值也不大，需要注意一下的是，如果你要学的是一个新的领域，又是一个很可能创新的机会，或者感觉这个价值并不大，但可以认识很多人，如果有时间也可以去看看。希望通过图3提醒时间有限的你，可以用这个四象限法去判断，看看自己认得的知识学习活动是不是可以优化，效率是不是可以提高？\u003c/p>","explains":"\u003cp>【学习目标】大家跟随我完成本次RIA现场学习后，能用“价值/时间”的判断方法，识别更有效率的学习方式。\u003c/p>\u003cp>I:\u003c/p>\u003cp>在拆书帮来的小伙伴们都是很有上进心的，所以大家肯定知道这时代是一个终身学习的时代，我们每天处理各种信息和知识，是知识工作者，但大家都能很好的学习知识吗？我们效率如何呢？\u003c/p>\u003cp>【细化行动步骤】作者给出了三个步骤帮助我们来确定：\u003c/p>\u003cp>1.判断学习该项知识的时间和产出的价值；\u003c/p>\u003cp>2.对应到相应的四象限中：\u003c/p>\u003cp>①\u003cstrong>投资\u003c/strong>花费时间短，获得价值高的活动--第2象限\u003c/p>\u003cp>②\u003cstrong>抛弃\u003c/strong>花费时间长，获得价值低的活动--第4象限\u003c/p>\u003cp>\u003cstrong>③斟酌\u003c/strong>花费时间长，活动价值高的\u003cstrong>替代方案\u003c/strong>--第1象限\u003cbr>\u003c/p>\u003cp>④根据时间情况选择花费时间短，活动价值有限或无法判断的活动，需要\u003cstrong>斟酌是否参加\u003c/strong>--第3象限\u003c/p>\u003cp>3.选择对应的方案。\u003c/p>\u003cp>【不那么做的坏处】（反面案例）前两年的时候，我经常会关注网络上各种的微课，因为那个时候在线的学习逐渐的发达起来，我们有各种机会去了解到很多我们欠缺的知识，比如阅读训练营啊，沟通训练营啊，那个时候如获至宝，花费了大量的时间和精力，每天都在网络上忙的不亦乐乎，也觉得自己学到了很多东西，直到某一天，突然发现这种碎片化的学习其实并没有打造出自己的学习体系，反而加深了知识焦虑，用低水平的勤奋掩盖了我的不足，读到本书的时候，用“价值/时间”的判断方法，我发现其实我一直在作者花费大量的时间，获得价值较低的活动，属于需要放弃的学习方式。\u003c/p>\u003cp>于是，在我重新梳理了我的需求之后，我对于各种学习方式按照上述三个步骤做了调整，因为我有创业的需求，所以在线下专业的培训课程和在线课程学习两种方案之间：\u003c/p>\u003cp>1.判断学习该项知识的时间和产出的价值——考虑到线下专业培训课程时间短，当面交流价值高；在线课程时间短，价值不确定；\u003c/p>\u003cp>2.对应到相应的四象限中——专业培训课程属于第2象限的学习方式，值得投资，在线课程学习属于第3象限，但目前时间比较有限，需要斟酌；\u003c/p>\u003cp>3.选择对应方案——所以选择了线下专业的课程培训，时间短、价值高。\u003c/p>\u003cp>【预防异议】当然也有朋友说，读书其实也是时间花费比较长，价值一时也看不出来的学习方式啊，是不是就不值得呢？其实读书是很快速的获取知识的方式，如果我们没有获得价值感，很有可能是因为我们读到的内容对当时当下并没有太大的作用，但未来也许会有，也有可能是因为我们还没有掌握读书的方法，对其中的知识也没有很好的使用。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>【显像提问】请小伙伴们回忆一下，你们过去一周你在学习的时候采用了什么学习方式？比如我就用喜马拉雅学习财富管理的课程，你是否通过报班学习准备职称考证呢？而这些学习方式属于哪个象限呢？\u003c/p>\u003cp>【案例记录】\u003c/p>\u003cp>小伙伴1：我买了张德芬的修心课，以调节自己情绪为主，是个网络课程可以用零碎时间来学习，时间很短我会把学到的内容融合到我的生活中，是投入时间短但是收获很高的方式，所以是值得投资的。\u003c/p>\u003cp>【回应·反馈】我：嗯，你买了网课，因为你运用的比较好，所以你觉得是属于第二象限的方式，很棒，说明你已经做到了的好的学习方式。\u003c/p>\u003cp>小伙伴2：我过去一周在拆书选片段，感觉属于第一象限，为什么呢？我感觉读了大量的书但是还是没有选出合适的片段，有些片段太模糊不符合要求。\u003c/p>\u003cp>【回应·反馈】我：嗯，你觉得花了大量时间但是产生的价值却不高。\u003c/p>\u003cp>A1+：\u003c/p>\u003cp>如果大家再遇到同样的问题，运用片段中方法，你们会怎么做呢？\u003c/p>\u003cp>【案例记录】小伙伴2：我想了下，如果采用最快的方式就是直接用别人的片段来拆。用他们的片段内容，但是按我的理解来拆。因为他人选择的片段已经是经过筛选的内容，我只需要投入较少的时间，就可以获得符合我需要的片段，是属于第二象限的可以投资的方式。\u003c/p>\u003cp>【回应·反馈】我：如果你确实在拆书选片段上存在困惑又希望快速升级打怪，确实是个不错的方式。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":8861,"quote":"\u003cp>片段二：\u003c/p>\u003cp>【学习目标】大家跟随我完成本次RIA现场学习后，能够运用学习模型学习目标领域的知识。\u003c/p>\u003cp>你的学习方法模型\u003c/p>\u003cp>如果你确定了自己的学习方向一一比如某个领域,那么就应该去学习这个领域的知识,才能保证你能够掌握这个领域的知识全貌,然后在工作中去利用这些知识并创造新知识。笔者认为主要是以下几个方面:\u003c/p>\u003cp>第一,掌握该领域的基础知识。\u003c/p>\u003cp>如果你不掌握这个领域的基础知识,那你对该领域的掌握就比较肤浅,很可能出现“无知者无畏”的情况,所以建议你要学习某个领域的知识,在起步阶段最好定下心来掌握该领域的基础知识。掌握一个领域基础知识的最好方法是先读教材,选择一本经过时间检验、比较经典的教材深人研读,不要怕是“人门、概论”一类。对于新的领域,每个人都要学习如何入门。弄清楚教材之后,你需要去读经典的书籍。哪些书籍比较经典,可以请有经验的人来推荐,也可以到网上去査看大家的评论。此外,可以读相关的经典论文。论文是否经典,可以通过引用数据来进行简单的衡量, Google学术搜索提供了按照论文引用数据排序的功能。\u003c/p>\u003cp>第二,了解该领域的全貌。\u003c/p>\u003cp>读完上述的书和论文,你对该领域的知识有了一个初步的理解和掌握,但是还没有形成比较全面的认识。这时候你需要大量地泛读以了解这个领域,简单的方式是利用搜索引擎。就笔者自己来说,我主要是做知识管理的工作,关于知识管理和相关的关键词,在搜索引擎(例如 Google和百度)前面100页的信息我基本上都看过一遍,通过这个广泛的阅读,我从各个角度了解了这个领域的信息和知识。接下来,你要确认领域内的专家是哪些人,与该领域的专家进行交流学习。\u003c/p>\u003cp>在有了基础,了解了全貌后,你可能就会开始从事这个领域的工作和利用这域,接触该领域的专家,反思自己的工作经验和教训等,以帮助自己不断提高。\u003c/p>\u003cp>第三,跟踪并掌握该领域的最新知识每个领域的知识都会根据需求和实践的发展而升级,社会的进步、技术的更新都会对知识产生影响,这个时候你需要持续地跟踪并学习。\u003c/p>\u003cp>你要明确需要跟踪的内容,包括显性的和隐性的。显性的包括报纸、杂志、新闻、论文,隐性的包括行业专家、参与讨论的相应社区。显性的内容大都以数字的形式存在,你可以用RSS订阅的形式订阅到自己的面前;隐性的内容你要保持与行业专家的定时交流、沟通。\u003c/p>\u003cp>通过跟进,你可以发现最新的趋势和规律,掌握你所在领域的进展,从而结合你的工作进行创新。\u003c/p>\u003cp>第四,在实践中学习和创新。知识的创新离不开实践,在实践中才能产生真正的创新。你需要在实践中总结自己的经验和教训,有意识地提升自己的显性化的知识水平和能力对于已经掌握的知识要多说、多写,争取能够用最通俗的语言讲清楚复杂的问题。\u003c/p>","explains":"\u003cp>【学习目标】大家跟随我完成本次RIA现场学习后，能够运用学习模型学习目标领域的知识。\u003c/p>\u003cp>I：\u003c/p>\u003cp>【拆页间逻辑关系-递进】\u003c/p>\u003cp>在大家通过上一个拆页了解你学习的时间/价值比，初步了解了该选择什么样的方式来进行学习，第二个拆页就是告诉大家如何建立自己的系统的学习模型：\u003c/p>\u003cp>【细化步骤】\u003c/p>\u003cp>1.打好基础：\u003c/p>\u003cp>①阅读经典教材\u003c/p>\u003cp>②阅读经典书籍\u003c/p>\u003cp>③利用Google学术，阅读经典论文\u003c/p>\u003cp>2.了解行业：\u003c/p>\u003cp>①通过搜索引擎泛读100页内容\u003c/p>\u003cp>②确认领域内专家并与之交流\u003c/p>\u003cp>③通过实践，反思经验教训\u003c/p>\u003cp>3.跟进发展：\u003c/p>\u003cp>①跟踪学习显性知识，如报纸、杂志、论文等\u003cbr>\u003c/p>\u003cp>②跟踪学习隐性知识，如行业专业和行业社区讨论等\u003c/p>\u003cp>4.实践创新：\u003c/p>\u003cp>①在工作中有意识地使用知识\u003c/p>\u003cp>②做完工作后复盘\u003c/p>\u003cp>③用最简单、通俗易懂的语言，解释清楚观点\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>大家知道彭小六吗？人称六哥，现在是日入20万的网红知识IP，也是简书一哥，他的爆红就很好的印证了这个模型。他是高效阅读的领导者，他的一篇文章《如何用30分钟读懂一本书？》，有3万多阅读、1600多点赞，他最开始进入的是拆书帮，在拆书帮升级打怪过程中看过很多的书籍，今天拆的书也被他提到，他跟很多知名的知识管理专家都是好朋友，比如萧秋水老师、秋叶老师、赵周老师，从他们那里汲取知识，他会积极参加线下活动，每周从镇江出发做动车去苏州等地方参加活动，从两小时生活圈到五小时生活圈，不断扩展去积累人脉和经验，进行面对面的交流，他6个之后就出版了《让你的未来现在就来》分享了他的阅读方法，后续开发了《知识管理训练营》课程，现在他与行动派合作，给自己创造的读书法命名为洋葱阅读法，接下来也是一系列课程正在变现了。\u003c/p>\u003cp>【预防异议】有小伙伴可能会说这都是很简单的方法啊，并没有特别之处，那说明你已经是一个高阶的学习者了，哈佛大学的认知研究中心创立者布鲁纳说“除非把一件件事情放进构造好的模型里，否则很快就会忘记”，今天的模型特别适合那些还没有在知识的海洋里建立起学习模型的人，作为高阶学习者可以自己去开发适合自己的模型，也就是实践创新中的一种很好的体现。\u003c/p>","interaction":"\u003cp>A3：\u003c/p>\u003cp>【场景演练】Tina，是一名刚入职一年半的行政助理，在未来的职业发展方向上她希望可以朝着企业内训师上发展，作为前辈的你采用今天学习模型的四个步骤，可以给到Tina怎样的学习建议呢，Tina又会定下哪些行动计划呢？\u003c/p>\u003cp>小伙伴1（前辈）：【打好基础】首先，Tina我会给你些基本的关于内训师的资料，让你了解了基础操作；\u003c/p>\u003cp>小伙伴2（Tina）：谢谢前辈。\u003c/p>\u003cp>小伙伴1（前辈）：【了解行业、跟进发展】建议你也多多去网络上或者书本上搜集相关的知识，如果你足够了解后，我可以介绍专门的老师帮你拟定职业生涯规划，培训你的沟通技能、解决问题的能力，确定你的规划发展方向等等。\u003c/p>\u003cp>小伙伴2（Tina）：好的，我会多去搜集相关的信息，也会跟行业内的同行多交流，希望前辈也多多介绍一些同行给我认识。\u003c/p>\u003cp>小伙伴1（前辈）：【实践创新】最后通过实践，给到你锻炼机会来成长。\u003c/p>\u003cp>我：\u003c/p>\u003cp>【回应·反馈】我：谢谢，请大家给他们掌声，虽然这本书距今已经比较久了，但大家都根据自己的工作内容进行了丰富，听起来确实是很不错的建议，而且也很清晰。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>【分布催化1】请小伙伴们想一想，在接下来各自的人生规划中，你想在哪个方面投入时间精力，并且又是产出很高的事情？\u003c/p>\u003cp>【分布催化2】如果要实现你的选择，按照今天学习的四个步骤，你会怎么样去做呢？请小伙伴在组内讨论一下，稍后我将请小伙伴来进行分享。\u003c/p>\u003cp>【案例分享】\u003c/p>\u003cp>小伙伴：我想在职业发展往培训师方面发展，但首先要把我现在健身教练的工作做好，未来可以培训其他的教练，所以要考一些比较专业的认证，并且要提升自己沟通表达等等能力，也要不断去了解分析我们这个行业的走向，我打算去跟已经在做培训师的朋友交流请教，咨询一下行业动态，需要考哪些认证的考试，现阶段也把自己放在一个培训师的角度去带会员。\u003c/p>\u003cp>【回应·反馈·简短重述】\u003c/p>\u003cp>我：所以你的目标已经确定了，去做一名健身行业的培训师，现在也知道如何着手去做，很好，谢谢你的分享。接下来我们请另外一位小伙伴来分享，大家来这里学习想要学到东西最重要的是去用，分享你的想法其实就是有意识地在使用你刚学到的知识点。\u003c/p>\u003cp>（第二个小伙伴比较腼腆，用了对话的方式进行沟通）\u003c/p>\u003cp>小伙伴2：我想做养生酵素。\u003c/p>\u003cp>我：嗯，你具体怎么做呢？\u003c/p>\u003cp>小伙伴2：去了解下养生的基本知识和行业知识，其实我是已经在做酵素生意了。\u003c/p>\u003cp>我：你是先做了，现在反过头来重新去了解行业，那你通过哪些渠道去了解呢？\u003c/p>\u003cp>小伙伴2：通过一些同行。\u003c/p>\u003cp>我：那些养生方面的理念还有书有看过吗？\u003c/p>\u003cp>小伙伴：没有……\u003c/p>\u003cp>我：那可能需要从最基础的开始补充你的知识。那你现在有多了解呢？\u003c/p>\u003cp>小伙伴：对，所以我要跟同行去了解，再结合实际经营进行创新。\u003c/p>\u003cp>我：是的，其实不管我们学习做什么都没有关系，关键是能把知识进行迁移，学会运用我们学到的步骤和方法在不同的领域进行套用。谢谢大家的分享。\u003c/p>\u003cp>【强有力的总结】著名的未来学家托夫勒在他的《权利的转移》中分析得出，人类历史上权利的来源已经从暴力、财富转移到知识，他提出”知识讲颠覆全球的权利格局“，在当今社会环境下，我们做的几乎所有工作都围绕知识而展开。《你的知识需要管理》介绍了知识管理的模型：学习、保存、使用、共享和创新的循环，我们今天重点讲到的是学习的方向提高我们学习效率，系统性学习模型帮助我们建立提高学习的成果，相信通过不断摸索和实践，我们每个人都可以打造自己的个人知识力。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1533106210000,"updated_at":1534064456000,"ria":true},{"id":2879,"topic":"雅美蝶莉拆书","learn_goal":"TF1-1练习","remark":"","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"野狸野狸","city":"济南"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是莉莉，拆书帮名字是野狸野狸，今天来过TF1-1。我没有什么特别的身份和经历可以与大家分享，目前最让我骄傲的身份是，新手拆书家。2016年我认识了拆书帮，2017年冲到北京听了帮主赵周老师的分享，随后得以荣幸地加入拆书帮，进入济南筹备分舵，认识了这里有趣有爱的小伙伴们。我在2017年的首要目标是成为三级拆书家，并且将拆书帮的学习方法分享给更多的人，让更多的人能够受益。 如果非要给自己加一点标签让大家记住的我话，那就是，我可以不需要中文字幕，就看懂日本的爱情动作片。哈哈，开个小玩笑，会日语，这算我另外一个能骄傲的技能点吧。好的自我介绍就到这里，谢谢大家。","ratings_count":0,"texts":[{"id":5657,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【图书】《你的知识需要管理》 &nbsp; \u003c/strong>\u003c/p>\u003cp>\u003cstrong>【章节】第五章第三节 &nbsp; 提升个人价值的方法\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【页码】P155-P156 \u003c/strong>\u003c/p>\u003cp>请大家用2分钟的时间我发给大家的拆页，阅读完抬头示意我就可以了，谢谢！好的可以开始阅读了。\u003c/p>\u003cp>经过以上对四个象限的分析，如何提升个人知识的价值就比较明确了。下面笔者给出几条简单的建议：\u003c/p>\u003cp>&nbsp; 第一，&nbsp; 向前看三年。\u003c/p>\u003cp>&nbsp; 在一定的社会环境中，对某领域知识的需求强度是我们无法改变的。但我们却可以掌握其中的规律，并利用这种规律。作为知识工作者，必须要有向前看的眼光，不要跟风、赶潮流，如果一味地追赶潮流，那你得到的很可能是残羹冷炙。你最好能找到两三年后社会需求会变大的知识领域，并能在这个领域学习和积累，这样当几年后该领域发展起来的时候你就可以获取高额收益（这个收益是你关注的内容，例如金钱、地位、安全感、尊重等）。但对于大部分在企业里做的人，你没必要也没有能力去预测十年后的社会需求，因为这个社会的变化实在太快了。\u003c/p>\u003cp>&nbsp;&nbsp;第二，&nbsp;&nbsp;持续提高你知识的独特性。\u003c/p>\u003cp>&nbsp;&nbsp;你能读硕士我也能读，你是博士我也是博士。如果个人知识的独特性单靠学历和证书的话，将来会越来越靠不住的，因为这些显性知识或者显性知识较多的学习不具备很高的壁垒，你必须要充分掌握你的行业，你的领域的隐性知识，必须多实践、多总结，这些包含你的经验、体验和操作的知识更难被别人复制，即更具备独特性。\u003c/p>\u003cp>&nbsp; &nbsp;提高个人知识独特性的路径有两条，第一条是在某方向上的专，这是基础，对于学生和处在职业生涯前十年的人而言至关重要，就如同前面所说的，你要在你的领域内达到行业前十名或前一百名的水平，这样无论你做什么都会有保障，都会又较强的竞争力；第二条是整合资源的能力，你能将相关的资源整合起来发挥出更大作用，这种综合实力更难以复制，创造的价值更大。这里面涉及知识的创新、知识的整合，需要个人远大的目标和眼光来支撑，需要战略决断能力、管理能力和执行能力作基础。\u003c/p>\u003cp>&nbsp; &nbsp;第三，&nbsp;&nbsp;通过知识共享树立你的个人品牌。\u003c/p>\u003cp>同样的商品，有的因为有品牌所以价格会贵，而且销量更大，讲究品\u003c/p>\u003cp>质的消费者都会倾向于选择品牌商品，这种趋势将随着社会发展和社会物质文明的提高愈发加强。每个知识工作者其实都要在社会的大环境中推广自己：让别人了解你、信任你并与你合作。在知识独特性差别不大的情况下，谁拥有品牌，谁就会得到更多的机会，所以每个知识工作者都应该打造自己的个人品牌。在第3象限中，你我都好像洗衣粉，如果你是拥有品牌的洗衣粉，在同样的知识水平下你的发展机会和薪水待遇很可能就更高。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;因此说，共享和传播自己的知识是建立个人品牌的好方法。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>拆书帮介绍：\u003c/strong>\u003c/p>\u003cp>在我的“自我介绍”中提到要将拆书帮的学习方法分享给更多的人。\u003c/p>\u003cp>那么什么是拆书帮呢?这里简单地介绍一下拆书法以及拆书帮。\u003c/p>\u003cp>“拆书”，并不是真的把好好的书给拆掉，它其实是一种成人学习方法。我们都经历过的学院式学习，强调的是以知识为中心。而拆书法，强调以学习者为中心，目的是学以致用。\u003c/p>\u003cp>它不要求拆书的人把书全部读完，而是将重点放在“用”上，把书中的一些知识片段联系学习者的经验并规划具体的应用。掌握了拆书法可以更好更快地学习运用自己需要的东西。\u003c/p>\u003cp>从形式来划分, 拆书法又分为&quot;个人学习拆书法&quot; 和 &quot;组织学习拆书法&quot; 。个人学习拆书法又叫RIA便签法，学习者用三张便签来将书本知识拆为己用，让人读一本书就获得参加一场同主题培训的效果。组织学习的拆书法是由一位拆书家用一本书加工出一场现场学习，带领学习者将知识拆为己用。\u003c/p>\u003cp>从学习效果来说，一位拆书家创造的价值不亚于一位培训师。\u003c/p>\u003cp>“拆书帮”正是基于拆书法而成立的学习爱好者社群，它是推动成人学习、终生学习的公益性组织。拆书帮在各地都有分舵，通过组织线上线下的各类拆书活动，推动更多学习爱好者成长为拆书家。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【I】\u003c/strong>\u003c/p>\u003cp>我们所处的这个时代，和三年前、五年前都不可同同日而语了。知识变现成为风潮，有的人能够很好地将自己掌握的东西分享，并因此获得了高额收益。提升自己知识的价值，在这个年代，变成了一个非常重要且必须的能力。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 除了提升个人知识的价值，这里提到的方法同样有利于帮助进入职场不久的人，进行自己的职业生涯规划。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 无论是出于什么样的考虑，需要帮助自己升值或是知识升值，我们都可以从下面这三点着手进行提升：\u003c/p>\u003cp>1、 找规律，找未来的社会需求，并从现在开始积累。\u003c/p>\u003cp>2、 拓展自己知识的专业度，以成为行业前十或前一百位为标准；整合专业领域内的各项资源，创造更大的价值。\u003c/p>\u003cp>3、 积极分享和传播，有意识地树立个人品牌，让别人了解、信任你，并和你合作。\u003c/p>\u003cp>通过上面的三点，我们或许可以获得高额收益，或许可以得到个人成长，或许能够做好职业生涯规划并完成生涯目标。无论如何，找到方向就去做，从眼下开始。&nbsp;\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>【A1】\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>公众微信号刚开始出现的时候，我不是很关注。直到2015年进入互联网公司，真正接触新媒体，我才知道用公众号可以做很多事。也亲眼目睹了一些大咖的崛起。\u003c/p>\u003cp>跟风开号，以为别人写情感能成功，我就行；以为别人骂街体能成功，我也行；以为别人的小黄文类型文章能火，我也行。这一年多，写了很多东西，又杂又乱。\u003c/p>\u003cp>但反观一位学姐，以日语为切入点，做日语电台课程，分享日本文化，读日本书籍和诗，分享日本的美照，如今她的公众号体量已经很大了。\u003c/p>\u003cp>而我的公众号至今依旧没有明晰的定位，我积累的日语知识、日本文化知识，通通没有利用，我积累的美妆护肤经验和知识，依旧没有利用。\u003c/p>\u003cp>同样，直播很火的时候，在线教育刚刚起来的时候，同样没有去做日语等课程分享，完美地丧失了经验积累的机会和成为最初那一批成功的人的可能。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【A2】\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>&nbsp;对公众号的规划：\u003c/p>\u003cp>1、 读书\u003c/p>\u003cp>进行快速读书法、主题阅读法的分享，输出相关文章；组织一周共读社群，从公司内部开始号召，随后转移到个人公众号。\u003c/p>\u003cp>2、 日语\u003c/p>\u003cp>千聊，日语专业知识的课程输出，继续50音课程等系列课程；大量输入日本文化及美妆、旅游相关内容，结合个人专业输出一系列文章；日本海淘等相关干货。\u003c/p>\u003cp>3、 定位好之后，寻找读书及日语领域的前30位公众号，分析优缺点，进行学习。补充并调整前两点的规划。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;4、加入的剽悍一只猫社群内，增加发言，积极交流，锻炼自己让被人信任的能力；尝 &nbsp; &nbsp; &nbsp;试争取其他平台的分享机会，如朝夕日历的平凡人分享（老姐做过），学习过来人经 &nbsp; &nbsp; &nbsp;验。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1497183844000,"updated_at":1497183912000,"ria":true},{"id":2616,"topic":"如何评判对知识的掌握程度及如何更好地调整完善自己的知识体系","learn_goal":"如何评判对知识的掌握程度及如何更好地调整完善自己的知识体系","remark":"","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"胡奇伟","city":"郑州"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫胡奇伟，关于我个人有三个标签：中国岩盐之都、早教、超级奶爸；我老家是平顶山叶县的，叶县的岩盐产量居全国之首，我们日常吃的盐全都是我们那儿产的，本人虽然是理科生，可是偏偏喜欢孩子，所以现在从事早教行业，孩子们也都喜欢我，所以老师们都说我是超级奶爸。平时喜欢看书，喜欢分享，希望能跟大家一起进步！\r\n今天我选的片段来自《你的知识需要管理》，作者田志刚。关于本书的简介：在这飞速变革的知识经济时代里，个人发展越来越依赖于个人竞争力。而个人竞争力的源泉则是个人知识力：即个人知识的学习，保存，传递和创新的能力。每个人都离不开个人知识力的培养和塑造。对于各类机构而言，提升知识员工的个人知识力也是组织效率提升，竞争力升级的基础工作。\r\n本书在亚马逊中国共105个评价，评论满分5分，平均评分4分，反馈还是不错的。\r\n我们学习了知识，可是如何评判对知识的掌握程度，如何更好的调整知识，这也是我们需要做的，今天我带来的就是与此相关的片段。","ratings_count":0,"texts":[{"id":5345,"quote":"\u003cp>&nbsp;“如果一件事情不能用通俗、简单的语言说出来或者写出来，证明你并没有全面地掌握或者掌握的深度不够”这句话，会帮助你在试图共享知识的过程中审视自己对知识的掌握情况，进而提升自己知识的水平。\u003cbr> &nbsp;&nbsp;从这个角度说，为了个人学习和成长得更快，为了能在某个知识领域中成为名列前茅者，你应该多说、多写。最简单的方法是，积极主动地利用各种机会去表达自己的观点。例如在学校或者公司开会的时候主动发言，在听讲座的时候主动提问。不要在每次参加集体活动的时候都找最不被人注意的地方，你要主动找机会去表达自己的观点和见解，并根据别人的反馈进行调整。如果实在不愿意或者不擅长说出来，那你就写出来：通过写文章、写博客、写论文、写书，你可以发现你的学习速度明显加快，对自己原来觉得理解和掌握的地方有了更深的体会，原来不清楚的地方更加明晰，从而做到日有所进！这样日积月累下来，你个人的成长会更快。\u003c/p>","explains":"\u003cp>&nbsp;能否将一件事情用通俗简单的语言表达出来是我们对知识掌握程度的一个很好的评判标准，也可以依此来提升自己的知识水平。从这个角度来说积极主动地利用各种机会，如集会、讲座甚至博客等，去表达自己的观点和见解，并根据别人的反馈进行调整，可以使自己学习和成长的更快，更好的成长为某个知识领域的名列前茅者。\u003c/p>","interaction":"\u003cp>A1：前两天参加了一个培训班，讲到“企业文化”时讲师讲的东西我特别有感触，然后讲师提问我们，关于刚才的话题谁能说说自己的理解？我想回答，可是又害怕错误，所以一直不敢吭声，别人回答了自己的看法，老师都给予指导评价，可是一直到最后我都没敢站起来说自己的看法，虽然我认为我的想法很好，可是然并卵，没有老师的指导和评价，那就始终是自己的看法而无从调整。\u003c/p>\u003cp>A2：下次再培训或者学习了新的东西，一定在现场或者我们的拆书帮线下活动自由分享活动中把自己学习的知识及看法及时有效地表达出来，和老师及朋友们一起讨论，并根据别人的反馈进行调整。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1494560933000,"updated_at":1494560933000,"ria":true},{"id":2407,"topic":"学习和提升的方法","learn_goal":"知识学习和提升的方法","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"grace","city":"福州"},"club":{"name":"福州闽江分舵","city":"福州"},"prologue":"《你的知识需要管理》是一本关于如何管理你的知识的书。在这飞速变革的知识经济时代里，个人发展越来越依赖于个人竞争力。而个人竞争力的源泉则是个人知识力：个人知识的学习、保存、共享、使用和创新的能力。每个人都离不开个人知识力的培养和塑造。对于各类机构而言，提升知识员工的个人知识力也是组织效率提升、竞争力升级的基础工作。 本书通过案例、问答等生动的形式深入浅出地阐述系统打造个人知识力的理念、方法、工具与技巧，使读者能够掌握提升个人竞争力、实现自我价值的流程和路径，是一本贡献给知识工作者的佳作。\r\n今天的分组是两个人一组，阿枫和丫丫一个组，晓庆和钱丹一个组。","ratings_count":0,"texts":[{"id":5105,"quote":null,"explains":"\u003cp>我是这样理解这个片段的：对于知识工作者来说，在工作中学习，做完事情之后的总结、提炼、提升是最大和最好的学习机会。如何进行总结需要你不断思考，在做不同事情的过程中寻找相似性，找到需要学习的“点”，制定出自己事后学习的模板，这样有意识地按照模板去总结和提炼，进而提高。\u003c/p>\u003cp>可以拆分为四个步骤：\u003c/p>\u003cp>第一步：在做不同事情的过程中寻找相似性\u003c/p>\u003cp>第二步：找到需要学习的点\u003c/p>\u003cp>第三步：制定出学习的模板\u003c/p>\u003cp>第四步：根据模板去总结和提炼\u003c/p>\u003cp>我在工作中以前也有做一些总结和提炼，比如我做的系列课程开发项目，对应以上的步骤\u003c/p>\u003cp>第一步：当我做完一个项目的时候，我会把做事的流程梳理出来。第二次再做这个项目的时候，我会去看是不是有共同点\u003c/p>\u003cp>第二步：在总结过程中，会发现做得不够的地方，比如发现去年最需要提升的是课程设计，所以就会在课程设计方面学习。\u003c/p>\u003cp>第三步：制定学习计划，比如自己要看多少本书，等等\u003c/p>\u003cp>第四步：在做完项目之后，进行总结，提炼出做得好的几个方面，做得不够的方面。然后去优化之前梳理出来的流程。\u003c/p>","interaction":"\u003cp>A1：不知道大家有没有工作后做总结的习惯？\u003c/p>\u003cp>或者大家有没有观察到身边的哪些人，他们有做总结、记录和分享的习惯？\u003c/p>\u003cp>比如我认识的一个老师，他就经常会把他做过的项目，项目的成功因素和失败因素写成文章跟大家分享。\u003c/p>\u003cp>请一些同学分享：\u003c/p>\u003cp>学习者1：平时工作团队有复盘，会做一些总结\u003c/p>\u003cp>学习者2：常用的项目会做总结，小事情不会做总结\u003c/p>\u003cp>学习者3：看书会做一些整理\u003c/p>\u003cp>A2：拆书家提问设计\u003c/p>\u003cp>通过以上的分享，对大家有怎样的启发？是不是有朋友想回去之后对最近的工作做一个总结和提炼？\u003c/p>\u003cp>我在3月份做了一场校长培训，通过校长培训的总结之后，感觉自己对于这个课程设计的认识加深了，进行工作总结对提升自己的水平很有帮助。\u003c/p>\u003cp>请大家写下应用所学的规划。\u003c/p>\u003cp>如果有时间，请一位同学分享：\u003c/p>\u003cp>学习者1：把项目写成简报交给处长\u003c/p>\u003cp>学习者2：复习RIA拆书法，建一个文件夹做记录\u003c/p>\u003cp>学习者3：提炼工作中培训带班值得总结的点，写成文章\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1492514780000,"updated_at":1498640302000},{"id":2125,"topic":"找到自己的共享之道","learn_goal":"能够知道共享知识的好处和途径，并且能找到适合自己的共享之道","remark":"","level":"TF2-1","duration":25,"status":0,"type":0,"chaishujia":{"username":"daisy_莼","city":"无锡"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是Daisy。今天我带来的主题是共享知识的捷径。今天这个主题呢，我是从《你的知识需要管理》这本书中找的拆页。【F】这本书的作者田志刚先生，是知识管理中心的发起人，高级咨询顾问，著名知识管理咨询专家，在这方面是很有权威的。这本书围绕个人知识管理中的学习知识、保存知识、共享知识、使用知识与创新知识五个环节来阐述我们该如何管理知识。阅读本书后你会发现，在我们管理知识的时候，并不是单单依靠其中一个环节就OK的，而是要五个环节去融会贯通才会达到知识有效的管理。【A】那为什么我要推荐这本书呢？因为我们管理类的书籍很多，这本书是管理类的一个分支--个人知识管理中写得比较细致的一本书。另外管理类的书籍都会比较深奥，而这本却写得十分通俗易懂。里面有很多案例，一看案例我们就能清楚他讲的知识点。另外他每个小结后面都有相关的工具推荐，这点就非常好，有些可以直接使用。【B】不知道大家有没有出了学校就不知道该学习什么知识的困惑？有没有看了一堆书籍或者文章，到需要使用的时候却找不到了的尴尬？还有就是学到很多知识以后却不知道如何去分享知识的担忧？如果你有类似问题，那通过这本书可以找到相关的答案","ratings_count":0,"texts":[{"id":4772,"quote":"\u003cp>【分组】那我先把现场分成两组，采薇和龙猫一组，陈忱和冬冬一组，待会儿方便我们分享经验，小组讨论。\u003c/p>\u003cp>【R】接下来我把片段发给大家，请大家用1-2分钟阅读下，看完了跟我示意一下。\u003c/p>","explains":"\u003cp>【I】好，片段比较简短，我看大家都看得差不多了。那我们为什么要进行知识共享呢？从小的方面来说，知识共享可以让我们更加理解这个知识点；往大的来说，我们可以树立自己的个人品牌，在社会上有一定的名誉和地位。那问题来了，有的人就会问，那我怎么去进行分享呢？大家第一反应肯定是演讲、论文，觉得这些是学究、教授做的事。那我们现在看一下片段里是有提到几个捷径的：\u003c/p>\u003cp>1、看完书就告诉别人我的读书感想\u003c/p>\u003cp>2、把自己的想法或者读书感想发到网站上，譬如公司网站、专业论坛等\u003c/p>\u003cp>3、别人发帖后，可以进行跟帖或者评论\u003c/p>\u003cp>4、更贴近我们生活的，就是平时的交流沟通。这其实也是一种共享的方式。\u003c/p>\u003cp>【强调不这么做的坏处】如果我们不进行知识共享会有哪些弊端呢？那譬如我们在日常沟通，我说了很多，你却不进行任何分享，那么第一你的存在感就会很低；第二人家不能认识到你，那对于你的薄弱处或者优点就不会有关注，那么你的进步速度就会变慢。所以，我们要去尽量地共享知识。\u003c/p>\u003cp>【A】接下来我讲下自己的经历。我个人一直在研究时间管理的知识，在实践方面也是比较有心得的。但是，我没有分享出去。于是，在工作的时候我会觉得为什么我一天能做这么多事情，你们却经常遗忘事情，为什么你们不去做这方面的管理。但现在我意识到，那是因为我没有把这个知识分享出去，我的同事可能并不懂时间管理，那他就没法配合我的工作。那如果我能共享这个知识的话，我们的配合能更默契。【案例】在这方面，我就认识一个我们外贸界的大咖，他就做的特别好。他在我们的外贸论坛写了他留学的经历、留学期间从商的经历、以及回国创业的想法由来等，他把这些都毫无保留地以故事的方式呈现给别人后，大家会对他这个人产生特别崇拜的感觉，对他也会觉得很了解，他在我们专业领域树立了个人品牌。所以当他回国创办外贸培训网站的时候，他的学员是爆炸式地增长。这就是一个知识共享带来的好处。\u003c/p>","interaction":"\u003cp>【显像提问】接下来，我想请大家想一下，今天我们参加了这样一个拆书活动，刚刚河马老师也分享了许多干货，我这边也分享到了知识分享的捷径，我想请大家回想下，以往的话，你们会如何去分享这样的经历和获得的知识。\u003c/p>\u003cp>【学习者案例】A：发朋友圈\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; B：和小伙伴口头交流\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; C：和伴侣闲聊，如果内容很好会写文章\u003c/p>\u003cp>【反思加工】接下来，我们通过这个知识点来做个实践。请大家回到过去想一下，能不能运用今天学到的捷径，让我们的分享途径能更精进。大家可以先写在便签上，然后写好的可以在小组内分享，每个人可以有1-2分钟的时间。\u003c/p>\u003cp>【学习者案例】A：可以知乎、豆瓣等去发表自己的文章和感想\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; B：可以在微信读书上分享自己的感想和观点\u003c/p>\u003cp>谢谢大家的分享。我希望这次分享的知识点大家也能运用生活中，尤其是我们常用的日常交流，大家能在生活中多去分享自己的观点和想法，这样也能得到别人的认同和赞赏。今天我的分享就先到这里，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1489243666000,"updated_at":1493863815000,"ria":true},{"id":1766,"topic":"如何保存“人”","learn_goal":"让学习者能实践做出自己的保存人的方法","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"daisy_莼","city":"无锡"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是今天的拆书家Daisy。今天我会通过一个片段带领大家找到自己保存“人”的方法。【分组】为了一会拆书活动我们能尽量的讨论和分享，我先把大家分成2组。右边两位是一组，左边两位是一组。\r\n【图书介绍】好，接下来我要介绍今天拆解的这本书，《你的知识需要管理》。这本书是我年初的时候在kindle推荐榜上看到的，当时在网上，那时候是知识大爆炸时代，然后在网上学习了很多很多东西，然后也真的是很迷茫怎么去把这些知识整理归纳保存成自己的知识，所以当时看到这本书的时候也是耳目一新，所以今天我想把这本书带给大家。这本书从5个方面在讲解我们该如何管理知识，包括学习、保存、共享、使用和创新，整本书中也有很多手操推荐。本书作者田志刚先生也是个人知识管理方面专业的人才，希望通过今天的拆解能对大家有一些帮助。","ratings_count":0,"texts":[{"id":4336,"quote":"\u003cp>下面我把片段发给大家，大家看一下。就看红框标出来的，从“如何保存人”到“否则时间一久就会忘掉”\u003c/p>","explains":"\u003cp>好，我看到大家差不多都看完了，这个片段也是比较简单的。\u003c/p>\u003cp>\u003cstrong>【I】\u003c/strong>当提到知识的保存时，我们是不是很容易想到资料、文档的保存，但很少想到对“人”的保存。这里的“人”指的是我们的人脉。工作、学习、生活中，我们会认识很多人或者获取很多名片，但如果对这些人的基本情况、背景情况和其他一些信息不加以整理保存的话，我们就不能有效的利用人脉，就不能快速获取。所以在这里，我们需要对人做一个保存，当需要联系某个领域的专家时就能快速获取。\u003c/p>\u003cp>\u003cstrong>【A】\u003c/strong>这一点我最近深有感触。因为生活中的朋友没有有效的储存方式，我最近换了手机后，很多人的手机号找不到了，我只能等着别人来联系我，这样是非常不方便的。而在我以前工作的时候，这一点就做的比较好。其实我们经常会忽略对生活中人的保存，会比较关注客户的保存。因为我以前是做业务的，在客户保存这一方面就会做的比较好。我会有一张excel表，在excel表中所有的客户信息都有，有关于他们的姓名啊、电话啊、生日这些基本的信息，也会有关于他们的产品、价格等这些特殊信息，也会有一些平时跟他聊天突然获取的信息，譬如，“噢，原来他喜欢动漫”就会记录下来，或者聊天发现他喜欢什么都会记录下来。每一次我们的聊天、或者邮件、或者通话，我都会把那天的主题记录下来。然后这样后期如果我遇到他，或者他拜托我来做事情，我对她的需求就会非常了解。所以对人脉的保存这些方面都是有非常大的作用。这样的话客户会比较信任你，以后跟你做业务也会比较顺畅，会觉得你这边比较方便。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验】【拆书家提问设计】\u003c/strong>\u003c/p>\u003cp>所以通过这个拆页的学习，我们也是发现了对人的保存是非常重要的。接下来，我希望大家在刚刚分好的小组内分享一下，你们平时都是如何保存自己亲戚、朋友、客户、同事等等的信息，并且回想下有没有去深入地了解过对方熟悉地领域或者正在做的事。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>阳槐分享：她通过这个片段想到曾经看到一个故事，说是有一个酒店，在客人第一次去的时候会记录下他们的姓名等基本信息，等客人第二次去，可以直接叫出他的名字，客人就会觉得很惊讶也很感动，所以这家酒店的口碑也特别好。\u003c/p>\u003cp>陈忱分享：最近去孩子家做家访，因为之前都是微信联系的，所以只是将微信名改为某某妈妈，最多再加个孩子出生年月日。但是积累的越来越多以后会发现开始混乱。哪些走访过哪些没走访过，没走访的家里是男孩还是女孩，具体问题是什么会忘记了。\u003c/p>\u003cp>\u003cstrong>【A2催化应用】【拆书家提问设计】\u003c/strong>\u003c/p>\u003cp>好了，通过刚刚地分享，我们发现在人的保存上我们还有待提升。现在，我们来实践一下，请大家挑选现场任何一位感兴趣的朋友，然后将她的信息保存在你的便签纸上。有不知道但想问的，也可以去问对方获取。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】\u003c/strong>\u003c/p>\u003cp>采薇针对陈忱做的信息采集表：\u003c/p>\u003cp>好，我看大家都交流的差不多了。然后今天我们这个便签上的内容可以回去复制到所有人的上面，然后整理成表格。好，我今天的拆解就到这里，希望对大家有帮助。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1483509991000,"updated_at":1488987992000,"ria":true},{"id":1692,"topic":"提升自我知识价值","learn_goal":"告诉我们通过向前看三年，成为一个领域的专才和树立个人品牌三个","remark":"","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"勤息","city":"无锡"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是新手拆书家勤息，今天由我来为大家拆书。我先把今天的拆书片段发给大家，大家都拿到了吧？在开始之前，我先帮大家分一下组，坐在我右手边的两位小伙伴分成一组，左手边的小伙伴分成另外一组。好的，下面开始拆书！大家对我都很熟悉了，就不必再自我介绍了，下面我来为大家介绍一下今天所要拆的书。这本书叫《你的知识需要管理》，我们都知道在这飞速变革的知识经济里，个人的发展越来越依赖于个人竞争力，而个人竞争力的源泉则是个人知识力：个人知识的学习，保存，共享，使用和创新的能力。本书通过案例、问答等生动的形式，深入浅出的阐述系统打造个人知识力的理念、方法、工具和技巧，使我们能够掌握提升个人竞争力，实现自我价值的流程和路径。下面请大家阅读一下刚才发给你们的片段。","ratings_count":0,"texts":[{"id":4283,"quote":null,"explains":"\u003cp>好了，时间差不多了，下面由我先向大家讲解一下我的便签！\u003c/p>\u003cp>I（用自己的话重述知识）：书中说了让自己知识升值的三个方法：1、向前看三年，为什么是三年呢？因为十年太久，未来变数太多，难以把握！一年半载又太短，没有参考价值，所以三年是比较适合的时间跨度。2、持续提高知识的独特性，主要是把握两点一是某个专领域上做到专业，二是提高整合自己资源的能力。3、通过知识共享树立个人品牌。\u003cbr>\u003c/p>\u003cp>A1（自己的相关经验）：以前有一个朋友问我，将来我是不是有竞争力？我回答她说当然有啊！我有正经大学的本科毕业证书，我现在的职业（公务员）是当前社会都认可的好工作，我还有考了很多证书，我怎么会没有竞争力呢？我的关心的重点停留在现在而不是未来，我看中的是证书而不是自己专业的能力，而且我也没有自己的品牌。\u003c/p>\u003cp>A2（规划自己的运用）：如果现在你问我，我是不是有竞争力，我会这么回答你：未来三年将是突出个性化的社会，是一个注重个人能力的社会！我现在到拆书帮，学习拆书便签法，提升自己的能力，就是为了未来三年甚至更久做准备，而且和小伙伴们一起提高自己的组织、演讲、逻辑能力，这都是很重要的专业能力，而且我会通过拆书帮分享知识，提升自己的品牌！所以，我相信，我在未来是有竞争力的！\u003c/p>","interaction":"\u003cp>结合这次的拆书学习，我们邀请一位学习者，向大家分享一下自己类似的生活和工作经验和自己今后做出哪些改变？\u003c/p>\u003cp>学习者1\u003c/p>\u003cp>A1：我是做外贸的，三年前做好纸质报关单比较重要，我没有去想三年后会发生什么，没有做好准备，只是去做好纸质报关这件事。还有就是外贸比较重要的英语、报关，操作等各方面能力，我各方面都不是特别强，没有专业强项。\u003cbr>\u003c/p>\u003cp>A2：现在的我会注重三年后的能力知识储备，我知道以后三年电子报关会变得越来越重要，我会加强这方面的知识学习。同时，我还会加强英语和报关等专业能力的培养，提升自己的专业应对能力。还要加强知识共享，提升自己的品牌和影响力，我相信按照这三个步骤去做，一定会有更强的竞争力的！\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482668228000,"updated_at":1482890388000},{"id":1691,"topic":"如何更好的交朋友","learn_goal":"通过区别手机联系人与朋友，和把这两类人区别对待的方法来做到有","remark":"","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"勤息","city":"无锡"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是新手拆书家勤息，刚才我已经把今天拆书的片段发给大家了，大家都拿到了吧？首先，我做一个自我介绍：我叫勤息，今年29岁，来自宜兴，大学是江苏科技大学，专业是机械电子工程，是高塍基层村委的一个村官，本人工作比较轻松，没有什么挑战和难度，所以，我想给自己一点压力，我在网上了解了拆书帮和拆书便签法，给我的启发很大，所以我就来到了这里，有幸和大家能够见面。那么是拆书和拆书帮呢？拆书帮是基于拆书法的学习爱好者社群，提倡通过学习改变行为，践行“把图书的知识转化为自己的能力”。拆书帮的拆书其实就是拆书便签法，就是将阅读分为：R（阅读片段）、I（用自己的话重述知识）、A1（描述自己的相关经验）和A2（以后我怎么应用）\r\nR：在读书时，遇到某一个心动片段，停下来，划出来。\r\nI ：用自己的话复述原文知识，达到理解知识本身是什么的程度。\r\nA1： 写和这个知识有关的自己的经验，通过反思自己的相关经验，让这个知识真的和自己有关。\r\nA2： 写下针对这个知识自己可以如何进行的下一步行动，让知识真的应用在自己的生命里，我们才能因为它变的更好。\r\n下面请大家用2分钟的时间读一下原文片段。","ratings_count":0,"texts":[{"id":4270,"quote":null,"explains":"\u003cp>这个片段讲的是如何交朋友，书中告诉我们两个方法：\u003c/p>\u003cp>1、在建立联系的同时尽量全面的保存联系人的资料、背景、爱好等各种情况。\u003c/p>\u003cp>2、区分普通联系人和朋友。普通联系人只需要收集此人的各种资料，做到联系的时候能够用上，心中有数即可；对于朋友就需要定期去维系感情，互相问候，提升各自的亲密度。\u003c/p>","interaction":"\u003cp>A1：我的手机里有二百多位联系人，但是我对他们的各种资料收集的都很少，了解不多，更没有把普通联系人和朋友作出区分，也没有经常和朋友联络感情，增进关系，所以我就很难交到很多好朋友。\u003c/p>\u003cp>A2：今晚回去，我要马上按照书中所说的方法来做。首先，我要把手机里的所有联系人的资料都做一个详细的表格，列出他们的各种背景和资料，增加对他们的了解；然后把其中是朋友的联系人单独列出来，做好标记，以后每个月定期或者在他们生日的时候对他们进行问候，增进彼此的友谊。这样我相信，我以后的朋友会越来越多的。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482668150000,"updated_at":1482804601000},{"id":1625,"topic":"碎片化知识的整理","learn_goal":"举例说明碎片化知识的处理方法。通过信息整理三步骤规划具体应用","remark":"","level":"TF2-4","duration":55,"status":0,"type":0,"chaishujia":{"username":"王锦康","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"【学习目标】在跟随我完成本次RIA现场学习后，学习者能够举例说明自己对碎片化知识的处理方法。\r\n【图书介绍】\r\nF： 这本书的作者是李参老师。在2014年经印象笔记美国总部的培训并通过考核，成为中国首批印象笔记企业咨询顾问。本书介绍了她多年来自己总结出的印象笔记私人用法。\r\nA： 所以这本书简单易操作，比如有个章节她写了如何用印象笔记既方便又实用地写晨间日记，她还附带了自己做的模板的下载链接。书中的很多类似的东西可以拿来就用，节约时间。\r\nB： 如果你想使用一款笔记类的软件却苦于不知如何上手，那么你就可以先通过模仿作者的方法来入门，然后摸索出自己的方法。如果你已经用了印象笔记一段时间却感觉还不得要领，那么你也可以看看高手是如何驾驭它的，从而对症下药提高自己使用软件的水平。\r\n所以我推荐有这方面需求的小伙伴可以买来一看。","ratings_count":0,"texts":[{"id":4180,"quote":"\u003cp>【片段一】：\u003c/p>\u003cp>相对于书籍的阅读来说，微博、微信公众号文章类的阅读会比较琐碎，不成体系。你了解的可能只是一个片段，如果没有自己的知识架构，又吸取信息过多，会很难将这些信息学以致用。过量的浅阅读和碎片化的阅读也会让我们的时间碎片化，我们本来想利用碎片时间进行阅读，没想到我们的时间却被不断碎片化。\u003c/p>\u003cp>我们使用微博或微信做的事情可以归结为以下三个部分：\u003c/p>\u003cp>刷；这个字大家都明白是什么意思，就是看你关注的人的动态以及他们的分享。这一点微博做得比微信好很多，通过分组，你可以关注很多乐于分享的人，他们仅仅发布微博，还会原创和转发一些文章。但每天看的微博，就那几个人的微博信息而已。\u003c/p>\u003cp>阅读：如果你关注很多乐于分享的人，那么可供你阅读的内容就会有很多，我们的大多数时间都会花费在这里。这样的阅读有一个缺点，那就是阅读的过程分散、无主题，而且内容很随机，哪方面的内容都有，虽然我们阅读了很多有价值的内容，但同样我们也会很快遗忘它们，这样的阅读，缺乏系统性。\u003c/p>\u003cp>互动：处理各种留言、评论，或者给别人留言、评论、转发。自己发微博或微信，其实也是互动的一种。\u003c/p>\u003cp>当我们停留在微博和微信时，有一个事情很可怕，你会发现时间过得飞快，不知不觉―两个小时就过去了，如果再因为看到了微博或微信的信息转而做其他事情那这种时间的消耗会更大。\u003c/p>\u003cp>而我们把时间耗费在这上面又觉得可惜的原因在于，明明花费了这些时间但是感觉收获却没这么大，获取的知识不够系统，没办法很好地为我所用。即使有价值的信息被印象笔记保存起来，也很难再次看到或利用到。\u003c/p>\u003cp>【片段二】：\u003c/p>\u003cp>首先，你要找到固定“刷”和“互动”的时间，刷微博、微信、淘宝、知乎的订阅，刷这个动作其实很快，哪些内容感兴趣，哪些不感兴趣很容易分辨。感兴趣的内容不要看，直接将这些内容保存到印象笔记。等这些都做好了后，就可以把这些APP关掉了。然后你就可以把打开印象笔记查看哪些你所保存的感兴趣的内容。\u003c/p>\u003cp>其次，我们可以把上网的时间转化成浅阅读时间。先整理好文章，再进行阅读，你收集的的信息涉及哪些主题，就建立哪些主题的笔记本，不要着急看，先把收集的文章移动到相关的笔记本后在进行阅读。\u003c/p>\u003cp>最后，是信息的加工。只有加工过的信息才是有价值的，你需要明确这一条信息的命名、分类和标签。如果你能做到这一点，那当你需要用到时，这条信息就一定能为你所用。之后，你可以对这一条信息进行重新编辑，或者加上你的感想，这些都是直接阅读微博或微信所无法比拟的。\u003c/p>","explains":"\u003cp>【片段一】拆书家讲解引导：\u003c/p>\u003cp>碎片化阅读的内容如果没有经过系统整理就不能为我们所用。刷微博看微信是现阶段碎片化阅读的代表。而我们在使用这两个APP的时候基本上是这三个动作：第一是刷，就是快速地浏览信息；第二是阅读，看到感兴趣的微博或者微信文章我们就会点进去看一看；第三就是互动，比如给作者留言评论或者觉得有价值有意思我们就转发。\u003c/p>\u003cp>这几个动作会耗费我们很多时间，包括我在内还有在座的一些小伙伴可能都会有这样的问题，就是忍不住拿起手机刷刷刷，结果放下收集一看，时光飞逝啊，然后内心充满了愧疚感。\u003c/p>\u003cp>但是这个并不在今天咱们讨论的范畴，今天的要讨论的是，明明花了那么多时间在看微博微信，里面也有很多有价值的东西，但为什么就是感觉收获没那么大，碎片的知识不够系统，没办法很好的为我所用呢。\u003c/p>\u003cp>我自己就有一个亲身的体会，就是之前我在过级的时候对FAB不是很清楚，于是就去网上搜索，结果提示在我的印象笔记里就有一篇关于如何写好FAB的文章（这里我插一句，就是如果你在浏览器里下载印象笔记的插件，那么印象笔记的相关内容也会出现在你的搜索结果里面）。看完之后我就在思考，这篇文章当时我确实觉得很有用也保存了，但是由于事后没有很好的整理和回顾，文章的知识并没有为我所用，甚至我都没有想起来我保存过这篇文章。\u003c/p>\u003cp>所以当我们在使用微博和微信的时候，如果不能去系统的整理和加工信息，那么它就不能为我们所用\u003c/p>\u003cp>【片段二】拆书家讲解引导：\u003cbr>\u003c/p>\u003cp>上一个片段中我们强调了碎片化阅读需要去系统的整理。那么这个片段，就告诉我们如何来整理。\u003c/p>\u003cp>原文的三段我用三个短语来总结一下就是：固定时间，先存后读，加工信息。首先我们要固定自己刷微博微信的时间；其次，当看到有价值的信息，先统一存到印象笔记中；最后，放下手机，打开印象笔记，在里面来阅读加工信息，明确它们的命名、分类和标签。\u003c/p>\u003cp>\u003cstrong>意译原文：\u003c/strong>在原文里作者用了班级加爱好的方法来解释分类和标签，这里我再给大家举个栗子就很好理解，就拿咱们拆书帮来说，一级二级三级拆书家就是分类，比如说春哥利芳姐和娜姐就归类到三级拆书家，薇淇姐就归类到二级拆书家，今天如果我过不了，那还是一级拆书家，然后我们这些人。同样是三级拆书家，她们三位又各有自己擅长的方面，比如春哥的擅长的沟通方法、职场技能等就可以作为他的标签。\u003c/p>\u003cp>\u003cstrong>坏处：\u003c/strong>如果我们看到有用的东西只是习惯性的点赞或者保存，而没有去加工整理，那么当你碰到一个问题，想到以前似乎看到过相应的方法却怎么也找不到，你花在碎片化阅读上面的时间并没有给你足够的回报。\u003c/p>\u003cp>\u003cstrong>异议：\u003c/strong>当然你可能会觉得，我每次看完微博微信还得去加工信息，那多麻烦多浪费时间呐，这里其实就是两种选择，一种是前期花一些时间去整理加工信息，后面需要什么迅速能搜索到，另外一种就是前期不保存或者只存不加工，到了后面用到了到处瞎找。哪一个更加高效省时大家肯定都明白。另外，其实也并不一定是看完信息马上就加工，你可以选择一天一加工，也可以一周一加工。这里提倡的更多还是要养成这种意识。\u003c/p>","interaction":"\u003cp>片段一【A1激活经验】\u003c/p>\u003cp>拆书家提问设计（逐字稿）： 说到这里，我就想请大家设想一下，某天你吃完中饭回到宿舍或者办公室，然后你拿起手机想看看微博微信，发现了一些你觉得很有价值的内容，那么一般情况你会怎么处理这些内容，是点赞、转发、收藏、保存还是其他方式，你可以举你最近做过的具体的例子，请大家在小组里讨论交流一下。\u003c/p>\u003cp>【学习者案例记录】：肖肖分享，因为我是做亲子教育嘛，所以经常会看这方面的文章，我看到文章一般会做截图保存，并且收藏在微信里，接下来写方案，方案写完之后就会把这段时间内收集的东西给删了。\u003c/p>\u003cp>片段二【A3促动参与】\u003c/p>\u003cp>拆书家提问设计（逐字稿）：刚才我们介绍了碎片化阅读整理信息三步骤，大家还记得是哪三个步骤吗？那么接下来我们就要来小组演练了。我们要做的事情就是模拟刷微博微信的过程，然后使用刚才介绍的三步骤来整理加工信息。\u003c/p>\u003cp>每个组都有20个信息，这些信息涵盖了时间管理、沟通方法、PPT使用等3个主题。首先，每个小组确定出你们组的要寻找的1个信息主题。接下来，快速的浏览所有信息，把符合你们主题的挑出来。最后，选定组里一位小伙伴来加工这些信息，给每一个信息都贴上2-3个便签，这些标签是方便你以后搜索的，所以你想怎么写都可以。\u003c/p>\u003cp>【学习者案例记录】：杏梅分享，我们组选取的主题是PPT，共找到了七个小材料和2个大材料，我们分成了三个层次，第一个就是PPT的制作，这个里面讲技巧的有水平复制、重复快速对齐。第二就是高颜值，这个材料我给它加的标签是最简化、美化。第三就是多积累多练习，学好PPT不仅需要技巧还要勤加练习，所以这个片段我给它加的标签就是练习。\u003c/p>\u003cp>【A2催化应用】\u003cbr>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：我们进行了一场演练，现在大家通过刚才我们说的三步骤规划一下自己以后的运用。固定时间、先存后读、加工信息。\u003c/p>\u003cp>我们要尽量具体化自己的应用，比如说，第一步固定时间，你会是在什么时间点来刷微博微信，是早上7点起床后、中午12点吃完饭回到办公室时、或者下午6点下班等公交地铁时，尽量具体到什么时间什么情景。\u003c/p>\u003cp>第二步确定你会做出保存动作的两个主题，第三步，确定加工信息的频率和数量。\u003c/p>\u003cp>【学习者案例记录】：罗鑫宇分享，我就是睡前会花半个小时到一个小时的时间来收集信息，读完之后也要加一个感想，便于后面的加工信息。我的主题一个是时政类，第二个是专业软件，每天收集并且加工5-6条信息。\u003c/p>\u003cp>【结语】刚才大家讨论的非常热烈啊，我希望通过今晚的学习，大家能够高效地使用印象笔记，把它打造为碎片化时代的私人利器。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1481960870000,"updated_at":1481960870000,"ria":true},{"id":1624,"topic":"如何分析知识共享的对象","learn_goal":"学习者能够复述分析知识共享对象的三步骤，并在演练中初步使用。","remark":"","level":"TF2-3","duration":25,"status":0,"type":0,"chaishujia":{"username":"王锦康","city":"长沙"},"club":{"name":"长沙橘洲分舵","city":"长沙"},"prologue":"【学习目标】在跟随我完成本次RIA现场学习后，学习者能够复述分析知识共享对象的三步骤，并在演练中初步使用。\r\n【图书介绍】\r\n今天我要给大家介绍的这本书，还是我上周拆解的《你的知识需要管理》，今天我想换一个角度来介绍。\r\nF： 这本书的作者是田志刚老师，他是中国最大的知识管理社区的创始人，也是中国知识管理领域重要的推动者，平时也经常会给各种组织和个人做知识管理的培训，所以他累积了大量的工作经验。\r\nA： 那么他写的这本书，案例非常丰富，不枯燥便于理解。比如书中提到我们电脑个人文件的命名体系，他就举了他服务过的几家公司的命名规则为例。\r\nB： 所以如果你厌倦了读那些理论知识丰富但枯燥无味的书，如果你希望能提高自己知识管理的能力和效率，你只需要看看这本书中的几个案例，在轻松阅读之后就能明白知识管理的大致内容。因此我推荐大家可以买这本书来看看。","ratings_count":0,"texts":[{"id":4179,"quote":"\u003cp>某年暑假的“科技三下乡”活动中，某农业大学的一些教授到农村去送科学技术。其中教养猪的王教授最受人们欢迎，因为他去的那个村是养猪专业村。其中村里有一家是养母猪的，别人围着王教授他进不去，最后才轮到他提问：“我们家有几头母猪不发情，这该怎么办呢？要是找不到方法就只能卖掉了！”\u003c/p>\u003cp>对于养母猪的农民来说，如何让母猪能有最高的产出是他最关注的问题。很不幸的是王教授对于母猪的繁殖实在是没有经验，于是想了半天说道“我记得引起母猪不发情的原因有二十多个，具体你们家的是哪个可能要去看了猪才能知道。主要的原因是1、2、3…“\u003c/p>\u003cp>没等王教授说完那个养母猪的老乡就走了，搞得王教授一脸尴尬。\u003c/p>\u003cp>王教授的错误在于他没有分清楚他知识共享的对象是谁。他所说的引起母猪不发情的各种原因都没有错，但这个农民其实需要的是个真正能解决问题的方法，最好是简单到“你买几片什么药给猪吃了”这样的话。因此，在做知识共享的时候，一定要记着你把知识共享给谁，即共享知识的“客户”是谁，他们习惯于什么样的方式，然后以他们能懂和能接受的方式去展现给他们，这样你的共享才能真正有效果。\u003c/p>\u003cp>在做知识共享的时候，你还要考虑共享对象的需求和习惯，对方更习惯于何种共享方式。如果你想将自己的一些知识共享给研究所的人，那就要将原理讲清楚，让他们自己去做判断；如果给对内容不太熟悉的人，那就要考虑尽量不用或者少用专业的术语，而用最平实的语言，最好能用比喻和生活中的例子等来让他们明白你的意思。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>当我们在做知识共享的时候，非常重要的就是对我们分享的对象进行分析。在这个关于王教授与母猪的片段里，就讲述了这样一个令人尴尬的事情。案例中的农民只想找到解决办法，但没有经验的王教授却开始滔滔不绝的讲原因。这样不把农民气走才怪呢，我想他走的时候肯定还会嘀咕，这个王教授真是一头猪。当然啦，虽然我也姓王，但我肯定不是猪。\u003c/p>\u003cp>那么以后我们在做分享的时候，该怎么对分享的对象进行分析从而避免类似尴尬的情况呢？我把片段的内容总结为以下三步：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp; &nbsp; 懂需求，需求包括两个方面：\u003cstrong>\u003cem>愿望\u003c/em>\u003c/strong>和\u003cstrong>\u003cem>能力\u003c/em>\u003c/strong>。愿望，也就是他想从你这里得到什么收获，是知识还是信息（比如片段里王教授给出的二十多个原因是信息，但是针对那户农民给出的某一个原因就是知识，因为知识是可以用来决策和执行的信息）。能力，特指理解能力。\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp; &nbsp; 知习惯，包括听众\u003cstrong>\u003cem>获取知识\u003c/em>\u003c/strong>的习惯以及\u003cstrong>\u003cem>习惯用语\u003c/em>\u003c/strong>，比如你面对一名大学生，那他平时是自主查阅资料解决问题还是求助他人寻求方法，喜欢看通俗读物还是专业读物，如果是后者，那你跟他说专业术语就没问题。并且如果你的用语能更贴近他的用语习惯，那他就会对你感到亲切。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp; &nbsp; 定方式，定下适合\u003cstrong>\u003cem>对方\u003c/em>\u003c/strong>以及当时\u003cstrong>\u003cem>环境\u003c/em>\u003c/strong>的方式。如果完成了以上两步，最后使用听众能懂和能接受的方式就是水到渠成的事情了。\u003c/p>\u003cp>以上就是分析知识共享对象的三步骤。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003cp>【A3】促动参与\u003cbr>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;拆书家提问设计（逐字稿）：我们刚刚学习了分析知识共享对象的三步骤。现在一起做一个演练。请大家认真听一下要演练的场景：\u003c/p>\u003cp>你们公司在一所高校体育馆内的大型招聘会设点招聘，应聘都是应届大学生，现场人很多，声音很嘈杂，这时候有一名大学生从隔壁公司过来坐下，递过一份简历跟你说，我想了解一下贵公司的基本情况。你看了他的简历，觉得这个人蛮优秀，想后续进一步了解。那么你在现场会如何与这位大学生介绍你们公司。\u003c/p>\u003cp>现在，先请两个小组就刚才提到的三步骤进行演练，演练结束我会邀请三位小伙伴，一位扮演公司人员进行介绍，一位扮演这名大学生，进行对话。另外一位小伙伴就他们的交流讲述你们组讨论的三步骤的内容。\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>刘波（饰演公司面试官），韩婕（饰演大学生）\u003c/p>\u003cp>刘波：你过来是应聘我们公司什么岗位啊？\u003c/p>\u003cp>韩婕：一个是成本岗，一个是投资发展。\u003c/p>\u003cp>刘波：看样子是对我们公司做过了解，非常好，我们就喜欢你这样子非常主动的学生。其实因为最近我们公司项目比较多所以成本岗的需求也比较大，那你对自己来公司有什么期待吗？\u003c/p>\u003cp>韩婕：我希望能有独立完成一个项目的机会，也希望未来的薪资和发展空间都能比较好。\u003c/p>\u003cp>刘波：好，那我给你简单介绍一下我们公司，我们公司是湖南的知名房地产企业，有56年历史，比较悠久。在梅溪湖也开了二期。另外你也提到了说想有很好的发展空间，正好我们公司也是近期开发了管培生的计划，会在2-3年内去打造出中层管理层的一批人。所以也是希望你能来我们公司做下一步的复试。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1481960495000,"updated_at":1481960495000,"ria":true},{"id":1387,"topic":"让你更加了解自己","learn_goal":"让你更加了解自己","remark":"你真的了解自己吗？你知道自己的优势在哪里吗？你眼中的自己和别人眼中的你是否是同一个人呢？一个小方法，让你知道在别人眼中，自己真正的优势是什么。","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"郭彦超","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好，我是超超，今天我要分享的主题是：一个小方法，让你更加了解自己。本次分享的片段来自于《你的知识需要管理》这本书。这本书是知识管理专家田志刚老师针对知识管理入门所写的，主要介绍了个人知识管理的方法。在我们的日常工作和学习中，都离不开对信息和知识的处理，而现在又是信息和知识爆炸的时代，如何才能提高自己处理信息和知识的能力？如何才能更好地学习而不至于落伍？这本书都会给你答案。","ratings_count":0,"texts":[{"id":3884,"quote":"\u003cp>确定你的学习方向之了解自己\u003cbr>如何确定自己学习知识的方向，根本就在于了解你自己，在确定目标的情况下发挥自己的优势。有一个方法可以让你了解自己，就是让熟悉你的人告诉你，他们感觉到的你的个人优势是什么，我们称之为“求求你，表扬我”。\u003cbr>在心理学上讲，你眼中的自己和别人眼中的自己是不同的，而从人的社会性角度而言，可能别人眼中的你才是真正的自己，他们可能更能清楚你的优势。\u003cbr>方法是选择10个最熟悉你的人，包括你的家庭成员、朋友、工作同事、上司、老师等，然后征求他们对你的认识。记住，这里征求的是在他们眼中你最优秀的部分，而不是对你的意见和建议，不是你的不足。上面已经讲到过，要成功，需要发挥你的优势而不是去补你的劣势，所以你征求的是在他们心中觉得你最优秀的地方在哪里。在做这个工作的时候，你除了要求他们说出你的优秀外，还要要求他们用例子来证明他们的观点。\u003cbr>如果你去做，你就会发现结果跟你心目中的自己不同，你会发现自己原来还有这么多的优势。\u003cbr>步骤：\u003cbr>1、选择10个最熟悉你的人；\u003cbr>2、写下自己寻求别人表扬的文本并标注好完成时间；\u003cbr>3、通过微信/短信/邮件发送给选定的对象；\u003cbr>4、收集反馈，发现未知的自己。\u003c/p>","explains":"\u003cp>我知道来拆书帮的小伙伴都是爱学习爱成长的小伙伴，不知道有没有小伙伴会有类似这样的困扰：我想学习，我想提高自己，但我不知道自己喜欢什么？又或者我想找到自己努力的方向，可是我不知道怎样才能找到它。之所以有这样的困扰，或多或少是对自己的了解不够。或许了解自己才是确定学习方向的第一步。\u003cbr>这个片段告诉了我们一个非常简单但十分有效的了解自己的方法，那就是让熟悉你的人来表扬你。很多时候我们以为的自己与别人以为的我们并不一样，从别人的视角来看自己，才能对自己有更深的了解。拿我自己来说，之前我一直认为自己是一个内向的人，之所以这么认为主要是自己在众人面前不太擅长表达自己，有了想法也不敢去说，害怕说错；又或者在很热闹的聚会中我常常不想说话，不知道要和别人聊些什么。后来，当我一遍遍听到别人评价我外向时，我很困惑，难道我不是内向的宝宝吗？所以当我告诉他们我明明很内向好么，我的小伙伴们都惊呆了，因为在他们看来，我根本不内向，没有人比我还能说了，甚至有一个朋友因为我平时喜欢吵吵，而叫我“吵吵”。所以我才恍然大悟，原来我是外向的人啊，而之后通过进一步分析我才知道之所以在人前不敢表达自己的想法是自信心不足，而之所以在聚会上不想说话，觉得孤独，纯粹是90后那抹淡淡的忧伤在作怪，不止我忧伤，很多人都忧伤。自从知道我是个外向的人之后，我有意识地确定了自己的一个学习方向，因为活泼外向时我的优势，我喜欢和别人交流，所以我更加注重沟通和表达的学习，我喜欢听我的师父懿琳拆书，也会积极完成师父布置的作业。之所以努力的做这些，就是为了锻炼自己的沟通和表达能力。\u003c/p>","interaction":"\u003cp>A1：这是我自己在受到别人表扬之后确定学习方向的案例。那么现在大家分小组，回顾一下，在之前的经历中，有没有人对你的夸奖让你对自己有了新的认识呢？比如在他夸奖了你之后，你发现原来自己还有这方面的技能，又或者原来我比想象中更有能力？请大家在小组内分享下。\u003cbr>A2：所以说呢，有的时候我们对自己的定义跟别人对我们的评价好像是有差别的。现在大家翻到片段的背面，我给出了一个模板，大家看过模板之后想一下自己请求别人表扬你时应该怎么组织属于自己的语言呢？然后在下面的答题框里写下以下几个要点，1、你打算什么时间请朋友来夸你呢；2、你打算请哪些朋友来夸夸你呢；3、你请他们夸你的时候你打算怎么组织语言呢？给大家5min的时间。\u003cbr>好了，在你写好怎样让别人表扬你的文本之后，就可以发送给选定的对象，让他们来夸夸你，相信你会在别人眼中看到不一样的自己。希望大家使用这个方法都能更多地了解自己，发现自己的优势，确定自己的学习方向，让自己在提高自我的路上越走越远。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1479808893000,"updated_at":1479808893000,"ria":true},{"id":1188,"topic":"个人知识管理","learn_goal":"学习者能够准确复述制定计划时过程思考的三要素","remark":"","level":"TF2-2","duration":18,"status":0,"type":0,"chaishujia":{"username":"王锦康","city":"长沙"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"【学习目标】在跟随我完成本次RIA现场学习后，学习者能够清楚了解提升个人知识价值的三步骤。\r\n【图书介绍】F：这是一本入门类的知识管理书籍，全书共分六个章节，首先总结了人们在知识管理上的误区，接下来从知识的学习、保存、共享、使用和创新五个部分详细阐述了知识管理的方方面面。\r\nA：它的全书架构很清晰，在每一章下面一般都遵从why-what-how的步骤阐述，比如说共享，它先说为什么要共享，接着说共享什么，再说怎么共享。\r\nB：所以你只要一翻目录就能马上知道你的问题该从哪个章节去找方法。如果你对着浩如烟海的知识不知道如何学习，学习了又对如何保存一头雾水，保存完又希望能够学以致用，创造价值。那么，你就不能错过这本书，它能很方便的让你对症下药，针对性地提升自己知识管理的能力和效率。\r\n在豆瓣上，秋叶大叔给了这本书满分的评价，盛赞了书的目录有着清晰的架构，所以我推荐有这方面需要的朋友可以买来看看。\r\n接下来大家看到的片段，就来自书中使用知识的章节。","ratings_count":0,"texts":[{"id":3426,"quote":"\u003cp>提升个人知识价值的三个绝招\u003c/p>\u003cp>第一.\u003cstrong>向前看三年\u003c/strong>。\u003c/p>\u003cp>作为知识工作者，必须要有向前看的眼光，不要跟风、赶潮流。你最好能找到两三年后社会需求会变大的知识领域，并能在这个领域学习和积累，这样当几年后该领域发展起来的时候你就可以获取高额收益。\u003c/p>\u003cp>第二.\u003cstrong>持续提高你知识的独特性\u003c/strong>。\u003c/p>\u003cp>你能读硕士我也能读，你是博士我也是博士。如果个人知识的独特性单靠学历和证书的话，将来会越来越靠不住，因为这些显性知识或者显性知识较多的学习不具备很高的壁垒，你必须充分掌握你的行业、你的领域的隐性知识，必须多实践、多总结，这些包含你的经验、体验和操作的知识更那被别人复制，即更具备独特性.\u003c/p>\u003cp>第三.&nbsp;\u003cstrong>通过知识共享树立你的个人品牌\u003c/strong>。\u003c/p>\u003cp>每个知识工作者其实都要在社会的大环境中推广自己：让别人了解你、信任你并与你合作。在知识独特性差别不大的情况下，谁拥有品牌，谁就会得到更多的机会，所以每个知识工作者都应该打造自己的个人品牌。\u003c/p>","explains":"\u003cp>&nbsp; 每个知识工作者都关注自己的价值，而知识工作者最主要资源就是个人知识的学习、保存、共享、使用和创新。那如何提高自己个人知识的价值呢？片段中作者列举了三种方法，我把它总结成三个四字短语，就是：眼光放远，知识学专，品牌做大。\u003c/p>\u003cp>&nbsp; 举例：最近我就在思考一个事情，如果我以后成为三级拆书家想去推广自己，那我应该往哪个方向发展。现在手机上微课有很多，像职场技能啊、时间管理啊手绘课啊，我发现好像讲阅读方法的不多，而我身边的许多同学不看书的原因，也是因为感觉读书太费时或者读了用不出，而且我也觉得在未来几年，想读书爱读书的人会越来越多，所以我就买了五六本关于阅读方法的书籍仔细钻研，希望提升自己在这一方面的知识价值。\u003c/p>\u003cp>&nbsp; 异议：可能大家心里多少会有点疑问：我工作很忙呐，要我再花时间去树立品牌没时间呀 或者是 我所学的知识和技能大家都会，根本没有任何独特性可言啊，又或者哎呀我这个人近视眼，看不了那么远的趋势可咋办。\u003c/p>\u003cp>&nbsp; 预防性讲解：其实我这里说的眼光放远，知识学专，品牌做大是三种方法，而不是三个步骤。如果你没时间树立品牌，那么你就在自己的工作中把自己的知识拔尖做深。如果你觉得自己的知识很大众，那你就去看趋势看发展，拓展以后有价值的知识。如果你说自己近视，额，那恐怕只能像我这样，戴副好看一点的眼镜吧。总之，这是三种方法，全用上那最好，如果不行，那就用一种最适合自己的吧。\u003c/p>","interaction":"\u003cp>【A2催化应用】第一步：以上是我的讲解部分，接下来需要大家来应用我刚才所说的三种方法。设想一下这样一个场景，有一天你回到家里，打开灯坐在书桌前，手机和电脑都传来收到信息的滴滴声，你深刻地知道这是知识信息快速更迭的时代，你偶尔会担心自己的知识有一天会过时，于是你打算做一些事情提升自己知识的价值，请大家想一想，你最希望用以上三种方法的哪一种提升自己的什么知识，原因是什么，请大家在小组内分享。\u003c/p>\u003cp>【学习者案例记录】林毅：我主要是想提升我在医学上的专业知识。\u003cbr>\u003c/p>\u003cp>【A2催化应用】第二步：好的，感谢林毅的分享。刚才他说了想提升自己医学上的专业知识，那么接下来就他提到的这个案例，我们一起来想想如果是你，你接下来会怎么去做，大家在小组内讨论一下具体的行动步骤。\u003c/p>\u003cp>【学习者案例记录】第一步我对未来三年的预估是在老年医疗这方面，因为未来中国会是一个老龄化社会，所以这方面的需求会很大。第二步专就是通过阅读科学哲学方面的知识来提升自己，整合资源上还需要去掌握统计学的知识和大数据的知识。第三步，和同事分享心理学统计学上的知识，对于就是把我们看的论文用通俗的语言来传递下去。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1477302818000,"updated_at":1481956714000,"ria":true},{"id":1133,"topic":"《你的知识需要管理》拆书活动","learn_goal":"学完后，能够掌握一种学习领域聚焦方和一个学习新领域的方法。","remark":"事件场景：在当今互联网技术如此发达，信息爆炸的时代里，我们每个人每时每刻、随时随地都能轻易获取各种的信息和知识，我们每天一睁开眼睛，拿起手机打开微信，朋友圈的各类趣闻趣事、群聊信息、各类微课，数以百计的订阅号推送的东东，都会扑面而来。而我们就象只捡了西瓜丢了芝麻的猴子一样，视乎留下不了多少东西在自己身上。回想一下，你昨天看的微信相关内容，你今天还记得多少？\r\n提问：遇到这种情况，我们如何做才能有效的管理这些知识，让它变成自己的能力，助力自己的发展呢？\r\n影响：若长期这样下去，我们就会被淹没在知识的海洋里，不知何去何从，个人能力的提升就更不要说了。\r\n解决：本书就提出了打造个人知识力五部法。","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"张然","city":"苏州市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我是拆书家张然，很高兴认识大家。我们进行报数分组，分为两组。本次学习目标是：学完后，能够掌握一种学习领域聚焦方和一个学习新领域的方法。\r\n我今天给大家带来的这本书名叫《你的知识需要管理》（场景法介绍图书）\r\n事件场景：在当今互联网技术如此发达，信息爆炸的时代里，我们每个人每时每刻、随时随地都能轻易获取各种的信息和知识，我们每天一睁开眼睛，拿起手机打开微信，朋友圈的各类趣闻趣事、群聊信息、各类微课，数以百计的订阅号推送的东东，都会扑面而来。而我们就象只捡了西瓜丢了芝麻的猴子一样，视乎留下不了多少东西在自己身上。回想一下，你昨天看的微信相关内容，你今天还记得多少？\r\n提问：遇到这种情况，我们如何做才能有效的管理这些知识，让它变成自己的能力，助力自己的发展呢？\r\n影响：若长期这样下去，我们就会被淹没在知识的海洋里，不知何去何从，个人能力的提升就更不要说了。\r\n解决：本书就提出了打造个人知识力五部法。这五步分别是学习知识、保存知识、共享知识、使用知识和创新知识。这五步就像个环，必须一一做到，知识才能转变成你的能力，是不是很想去了解其中内容呢？","ratings_count":0,"texts":[{"id":3351,"quote":"\u003cp>音频地址(开场中放不下，故放这边）：\u003ca href=\"http://note.youdao.com/noteshare?id=ea17ac2fcaa738898af25767b329cd03\">http://note.youdao.com/noteshare?id=ea17ac2fcaa738898af25767b329cd03 \u003c/p>\u003cp>个人知识的价值由两个因素决定：\u003c/p>\u003cp>第一个因素是你的知识的独特性。如果你仅仅认识26个英文字母，绝对不可能找到一个翻译的工作；如果你仅仅掌握了加减乘除，也没有一个机构敢请你去做会计。现在学历很热，许多人都有硕士、博士的学位，很多人认为如果一个人没有大专以上的学历，就根本没有办法在社会上立足。其实追求学历就是追求知识独特性的表现，现在有许多正在读书的学生热衷于考取各种证书，其本质也是在用证书来证明自己在某领域中知识的独特性。\u003c/p>\u003cp>知识的独特性也分两种，第一种是专，在某个方向上深入，别人都不如我深，所以我有独特性，比如读博士基本上是这个意思，还有一种是博，我既会拍电影又会画画，还会说相声、做木匠，这样的人以综合优势树立自己的独特性。\u003c/p>\u003cp>这里有一个例子：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 有个人要买鹦鹉，去了商店。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 店主介绍说：“这只500元，那只1000元，另一只2000元。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 这人问：“你的鹦鹉怎么这么贵？那你倒先说说看，这只的500元的会做些什么呢？”店主说：“这只会操作电脑。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 又问：“那这只1000元的呢？”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 店王说：“这只不但会操作电脑，而且还懂UNIX作业系统。”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “那么这只2000元的呢?”\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; “老实说，我还真没见过它做过任何事，不过另外两只都管它叫‘老板&#39;。”\u003c/p>\u003cp>从本质上讲，这位“老板”具备了整合资源的能力，他可以将许多资源整合在一起，这是他个人知识的独特性。电影导演也是整合资源的典型代表。\u003c/p>\u003cp>那是不是说拥有了知识的独特性就可以提升自己知识的价值呢？在《庄子·列御寇》中讲了一个故事：“朱泮漫学屠龙于支离益，单千金之家。三年技成，而无所用其巧。”这就是著名的屠龙术的故事。这个叫朱泽漫的用三年时间，花费千金，学成了屠龙术，但很可惜“无所用其巧”，为什么呢?因为没有龙，谁也没见过龙。所以他学屠龙术还不如学习杀猪，因为会杀猪也算一种专业技能，起码可以找到一份工作。这就涉及提升个人知识价值的第二个因素。\u003c/p>\u003cp>第二个因素是社会对知识的需求。学习屠龙术的成本不不菲，耗资巨大，时间需要三年，金钱需要千金，自然是门好技术，但到哪里去找到龙呢？因为找不到龙，所以这些技术知识毫无用处。所谓的“男怕入错行”其实就是这个意思，因为这个行当的需求很少，哪怕你有通天的本事，也很难获取较大的成功。\u003c/p>\u003cp>如果你的知识社会没有需求，那么这些知识的市场价值堪忧，当然，如果你的知识是为了陶冶情操，为了修身养性则另当别论了。\u003c/p>","explains":"\u003cp>我现在开始进行I\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;从本拆页能够知道，你的知识值多少钱是由哪两个因素决定的呢？\u003c/p>\u003cp>第一个因素是你的知识的独特性（意味着获取成本很高，要掌握它学习时间很长）；\u003c/p>\u003cp>第二个因素是社会对此知识的需求。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;如果我们把个人知识的独特性和社会对知识的需求结合起来，就形成了四个象限（顺序是 四&gt;三&gt;二&gt;一）：\u003c/p>\u003cp>第一象限：独特性低，社会需求低 叫作没有门槛的操作型人才，代表人物：公共汽车售票员\u003c/p>\u003cp>第二象限：独特性高，社会需求低 叫作专家，代表人物：地震救灾人员\u003c/p>\u003cp>第三象限：独特性低，社会需求高 叫作知识工作者，代表人物：大学生\u003c/p>\u003cp>第四象限：独特性高，社会需求高 叫作知本家，代表人物：百度创始人 李彦宏\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 无疑我们都要让自己处在第4个象限，我们现在就要将自己掌握的关键知识领域放到这个坐标系中，就知道我们要重点发展的知识领域会是哪些了。可以分以下四步走：\u003c/p>\u003cp>1.罗列；罗列自己希望掌握的关键知识有哪些？问：你希望掌握的关键知识有哪些呢？\u003c/p>\u003cp>2.打分；就个人知识独特性和社会对知识的需求两个维度对这些知识打分（1-10）\u003c/p>\u003cp>&gt;就独特性可以问：XX知识就知识独特性，1到10分打分，1分代表独特性很少，意味着很容易掌握或学到，10分代表独特性很高，意味着学习成本很高，要掌握需要很长的时间，你觉的要打几分？\u003c/p>\u003cp>&gt;就社会需求可以问：XX知识就社会对知识的需求，1到10分打分，1分代表未来需求很少，10分代表未来需求很高，你觉的打几分？\u003c/p>\u003cp>3.放入；将每个知识放入坐标系中，&gt;6分的表示高，&lt;=6分表示低\u003c/p>\u003cp>4.排序；从几个象限的排序来说，顺序是 四&gt;三&gt;二&gt;一，其中第四象限是重点要发展的知识了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 你可能会问我目前还不知道自己喜欢什么，不知道自己希望掌握的关键知识是那些怎么办？这个就不在本拆页的解决范围之内，这个要解决就要运用到本书确定你学习方向的四步法来解决了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 你也可能会问，我如果不知道这个知识的社会需求怎么样，这怎么办?那这个就是你接下来要做的功课。\u003c/p>\u003cp>也就是说这个工具运用在你对你希望掌握的知识有一定的了解基础上的，若一无所知，这个工具就不适用了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 我就会用此工具来确定自己重点发展的知识是哪些上。\u003c/p>\u003cp>1.你希望掌握的关键知识有哪些呢？\u003c/p>\u003cp>&nbsp; &nbsp;我希望掌握的关键知识有个人知识管理、时间管理、IT技术、PPT技能、九型人格、教练技术 、讲师技术、MBA、拆书技术\u003c/p>\u003cp>2.就个人知识独特性和社会对知识的需求两个维度对这些知识打分（1-10）\u003c/p>\u003cp>3.将每个知识放入坐标系中，&gt;6分的表示高，&lt;=6分表示低\u003c/p>\u003cp>4.看四象限的知识有哪些，这些就是重点要发展的知识了。\u003c/p>\u003cp>重点发展：教练技术、九型人格、讲师技术 、MBA，我最核心发展的就是教练技术了。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>我现在进行A2\u003c/p>\u003cp>在学习或希望掌握的关键知识有哪些，其中哪些要重点发展那些呢？请想一下，编一段小故事，假设有一位A，A是位你非诚信赖的并相信他有能力帮助你的人，这个人可能是你的偶像、领域专家或一个德高位重的长辈，设计一个你们相遇场景，情节变化（包括：起因、经过、结果）和你们的对话、动作等，其中A的问话使用上面的方法。让A来帮你找到你重点发展的知识，自已写完后，小组讨论下。时间4分钟，4分钟后我会请一个小组分享下他的剧本。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>拆书家：看起来大家都已讨论完了，我们请第一组来分享下他们的剧本。\u003c/p>\u003cp>第一组：自我介绍下，我叫多多。场景是这样的，正好下班，碰到我的旧同事，会跟他聊很多，这一天他正好和我聊起了工作上的事情，我们聊到了最近工作上的困惑点，他给我一些引导和帮助，他会对我说：\u003c/p>\u003cp>\u003cstrong>朋友：\u003c/strong>\u003cstrong>你认为你目前工作中需要的关键知识点是那些呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>\u003cstrong>我想了想，从我的个人职业出发，我是做HR的，首先是我的沟通能力，第二个是我的协调能力，还有就是时间管理，还有一项非常重要的就是我的进阶HR知识，我就向他罗列了这四个关键知识点。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：\u003c/strong>\u003cstrong>你觉的在这四项关键知识点中，从它的独特性和社会对他的需求性，1到10分，你会打多少分呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>\u003cstrong>我考虑了下，\u003c/strong>\u003c/p>\u003cp>\u003cstrong>项目 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;独特性 &nbsp; &nbsp;社会需求 &nbsp; &nbsp; 相乘得分\u003c/strong>\u003c/p>\u003cp>\u003cstrong>沟通能力 &nbsp; &nbsp; &nbsp; 7 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 8 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;56\u003c/strong>\u003c/p>\u003cp>\u003cstrong>协调能力 &nbsp; &nbsp; &nbsp; 4 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 8 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 32\u003c/strong>\u003c/p>\u003cp>\u003cstrong>时间管理 &nbsp; &nbsp; &nbsp; 6 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 8 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 54\u003c/strong>\u003c/p>\u003cp>\u003cstrong>进阶HR知识 &nbsp; &nbsp; 8 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 8 &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 64\u003c/strong>\u003c/p>\u003cp>\u003cstrong>打完分后，同事会给我进行了一些分析\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>朋友：\u003c/strong>\u003cstrong>将关键知识点罗列到坐标系中，你会发现什么呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>我：\u003c/strong>\u003cstrong>我发现关键知识点和能力发展聚焦在专业进阶HR知识和沟通能力两方面\u003c/strong>\u003c/p>\u003cp>跟他聊完后，非常愉快，就很轻松愉悦的结束了此次对话\u003c/p>\u003cp>拆书家：很棒，剧本描写的场景也很好，掌声鼓励下。有一点我再提一下，你提到的专业进阶HR知识会包含哪些具体内容呢？此部分可以再细化，按照这四步法进行，可能会更加聚焦。这个片段的拆解就到这边。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":3352,"quote":"\u003cp>\u003cstrong>你的学习方法模型：\u003c/strong>\u003c/p>\u003cp>如果你确定了自己的学习方向 ——比如某个领域，那么就应该去学习这个领域的知识，才能保证你能够掌握这个领域的知识全貌，然后在工作中去利用这些知识并创造新知识。笔者认为主要是以下几个方面： \u003c/p>\u003cp>第一，掌握该领域的基础知识。\u003c/p>\u003cp>如果你不掌握这个领域的基础知识，那你对该领域的掌握就比较肤浅很可能出现“无知者无畏”的情况，所以建议你要学习某个领域的知识，在起步阶段最好定下心来掌握该领域的基础知识。\u003c/p>\u003cp>掌握一个领域基础知识的最好方法是先读教材，选择一本经过时间检验、比较经典的教材深入研读，不要怕是“入门、概论”一类。对于新的领域每个人都要学习如何入门。弄清楚教材之后，你需要去读经典的书籍，哪些书籍比较经典，可以请有经验的人来推荐，也可以到网上去查看大家的评论。\u003c/p>\u003cp>此外，可以读相关的经典论文。论文是否经典，可以通过引用数据来进行简单的衡量，Google学术搜索提供了按照论文引用数据排序的功能。\u003c/p>\u003cp>第二，了解该领域的全貌\u003c/p>\u003cp>读完上述的书和论文，你对该领域的知识有了一个初步的理解和掌握，但是还没有形成比较全面的认识。这时候你需要大量地泛读以了解这个领域简单的方式是利用搜索引擎。就笔者自己来说我主要是做知识管理的工作，关于知识管理和相关的关键词，在搜索引擎（例如Google和百度）前面100页的信息我基本上都看过一遍，通过这个广泛的阅读我从各个角度了解了这个领域的信息和知识接下来，你要确认领域内的专家是哪些人，与该领域的专家进行交流学习。在有了基础，了解全貌后，你可能就会开始从事这个领域的工作和利用些知识来帮助你的工作。但你的学习还没有结束，你还需要持续地跟进这个领域，接触该领域的专家，反思自己的工作经验和教训等，以帮助自己不断提高。\u003c/p>\u003cp>第三，跟踪并掌握该领域的最新知识。\u003c/p>\u003cp>每个领域的知识都会根据需求和实践的发展而升级，社会的进步、技术的更新都会对知识产生影响，这个时候你需要持续地跟踪并学习。\u003c/p>\u003cp>你要明确需要跟踪的内容，包括显性的和隐性的。显性的包括报纸、杂志、新闻、论文，隐性的包括行业专家、参与讨论的相应社区。显性的内容大都以数字的形式存在，你可以用心订阅的形式订阅到自己的面前；隐性的内容你要保持与行业专家的定时交流、沟通。\u003c/p>\u003cp>通过跟进，你可以发现最新的趋势和规律，掌握你所在领域的进展，从而 结合你的工作进行创新。\u003c/p>\u003cp>第四，在实践中学习和创新。\u003c/p>\u003cp>知识的创新离不开实践，在实践中才能产生真正的创新。你需要在实践中总结自己的经验和教训，有意识地提升自己的显性化的知识水平和能力，对于已经掌握的知识要多说、多写，争取能够用最通俗的语言讲清楚复杂的问题。\u003c/p>","explains":"\u003cp>【A1】请大家自测\u003c/p>\u003cp>知道了自己要重点发展的知识或领域后，要如何发展呢？有什么方法吗？下面一个拆页就给出了答案。大家先花1分钟时间做下自测题，看看自己发展新领域知识的能力如何？\u003c/p>\u003cp>【I】解释自测题\u003c/p>\u003cp>分数代表你发展新领域知识的能力如何？\u003c/p>\u003cp>4~10 你发展新领域知识的能力急需提高\u003c/p>\u003cp>11~15 你发展新领域知识的能力尚可，可关注薄弱环节\u003c/p>\u003cp>16~20 你发展新领域知识的能力很强，继续加油\u003c/p>\u003cp>要如何进行发展，就要看下面拆页了。\u003c/p>\u003cp>【R】阅读原书拆页\u003c/p>\u003cp>我今天截取的片段是：你的学习方法模型，请大家先看一下片段，给大家2分钟时间，看完了可示意一下我。\u003c/p>\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>我现在开始进行I\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 本文给出了学习新领域知识的四个步骤，是哪四个步骤呢？\u003c/p>\u003cp>1.掌握该领域的基础知识（打好基础）\u003c/p>\u003cp>2.了解该领域的全貌（了解行业）\u003c/p>\u003cp>3.跟踪并掌握该领域的最新知识（跟进发展）\u003c/p>\u003cp>4.在实践中学习和创新（实践创新）\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; 每个步骤都有一些方法可参考。\u003c/p>\u003cp>一、打好基础；学习内容包括：\u003c/p>\u003cp>&nbsp;书籍：选择简单、经典的入门和概论书籍\u003c/p>\u003cp>&nbsp;经典论文、文章：引用次数最多的论文、被收藏最多的文章\u003c/p>\u003cp>二、了解行业；阅读关于你关注领域搜索引擎的前50页内容，形成对行业的感性认识\u003c/p>\u003cp>与同行人士交流，获取隐形知识\u003c/p>\u003cp>三、跟进发展；跟进对象包括\u003c/p>\u003cp>&nbsp;&gt;相关书籍、期刊、杂志\u003c/p>\u003cp>&nbsp;&gt;互联网信息\u003c/p>\u003cp>&nbsp;&gt;行业论文\u003c/p>\u003cp>&nbsp;&gt;行业专家的观点、博客等，争取能够面对面交流\u003c/p>\u003cp>&nbsp;&gt;参与行业的社区交流（研讨会、网路论坛等）\u003c/p>\u003cp>四、实践创新；在工作中有意识地利用知识，做完每项工作后进行回顾和总结\u003c/p>\u003cp>有意识地做知识显性化的工作，写出你的观点和体会，充分利用机会说出自己的看法\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 有人可能会问，四步必须都要做么？我的实践体会是，都需要做，而且一个也不能少。甚至在某些步骤会有反复迭代的情况发生。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;我就用在我学习九型人格的领域知识中：\u003c/p>\u003cp>1.打好基础\u003c/p>\u003cp>&nbsp; &nbsp;&gt;阅读海伦.帕尔默的所有书籍\u003c/p>\u003cp>&nbsp; &nbsp;&gt;花钱上九型人格的一阶和二阶班\u003c/p>\u003cp>2.了解该领域的全貌（了解行业）\u003c/p>\u003cp>&nbsp; &nbsp;&gt;给行业的导师例如立波和子钰导师交流了解行业\u003c/p>\u003cp>&nbsp; &nbsp;&gt;广泛阅读领域知识，了解行业全貌\u003c/p>\u003cp>3.跟踪并掌握该领域的最新知识（跟进发展）\u003c/p>\u003cp>&nbsp; &nbsp;&gt;加入社群，参加全世界九型大会跟进发展\u003c/p>\u003cp>4.在实践中学习和创新（实践创新）\u003c/p>\u003cp>&nbsp; &nbsp;&gt;觉察自己和家朋友，总结经验教训\u003c/p>\u003cp>&nbsp; &nbsp;&gt;将所学运用在亲子教育中\u003c/p>\u003cp>&nbsp; &nbsp;&gt;在公司开公开课\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>我现在进行A3：\u003c/p>\u003cp>请在小组内讨论：我们知道知识只有用才能掌握，正所谓练习，练习，再练习，这七字真言百试不爽，可见第四步实践创新的重要性。请脑力激荡下，我们有哪些实践创新的方法呢？请把讨论出的方法记录在一张白纸上。7分钟后，我请每组派代表来讲解你们的成果？\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>拆书家：看大家经过激烈的讨论后已经有结果了，你们有哪些实践创新的方法呢？请第二组先进行分享。\u003c/p>\u003cp>第二组：我将我们三个人想到的实践创新方法编成一个故事。有一个人到了一个新的单位，从明天开始他有一个新的工作环境和有新的工作要求。明天开始他也有一系列的培训，是关于工作上的技能的培训。他学习完后，一方面会进行总结分享，也会结合新单位和新领域的实际情况，构建新的体系和新的方法，有实践有创新。在构建新体系的过程中，他压力很大经常失眠，他就用到一套叫做内观的方法，用中午的时间，用佛家的思想让自己的内心平静下来，反复的内观自己，创新力也大大加强。因经常在外工作，家庭疏于照顾，小孩生病，他就结合用多年以来适合他孩子的配方，通过自己的观察结合别人的案例，进行创新，配制出了专门针对他家小孩的配方，治疗效果非常明显。\u003c/p>\u003cp>拆书家：好棒。我从中有听到几个方法，第一个是学习后立即用到工作中去。第二是他会输出进行分享，第三将内观用起来，来加强创新。最后他很善于将学到知识用到自己生活中去，进行生活化，这样每天都会用。非常棒的方法，大家掌声鼓励下。我们来请第一组来进行分享。\u003c/p>\u003cp>第一组：我们这边总结了下，主要是三个方面的方法，第一个是分享，第二个是记录。第三个是练习。分享就是可以和自己的同行进行讨论，可以互相进步和学习。再来就是讲述，讲给自己身边的人听，把别人讲懂了，自己才真正学会。第三个就是自己做讲师，这个对自己学习的要求就很高了。第二个是记录，我们组的同学提到用X-Mind，就是思维导图来笔记，图画出来便于自己记忆，别人也能很容易看懂。另外就是做笔记，我是做翻译的，就可以在会议时或听课时，心得体会用英文来进行记录。不仅仅复习了课程内容有练习了翻译，这也是练习的一种方式。第三个就是练习，每个人练习的方式不一样，平时就多用碎片化的时间进行练习。\u003c/p>\u003cp>拆书家：就这个练习的场景和方法，能否分享的一个具体例子？\u003c/p>\u003cp>第一组：就拿上周六的拆书课来说，学习到的方法，我回去就找人讲，发现有些没有理解进行了反思，再进行了学习。\u003c/p>\u003cp>拆书家：这是很好的方法，掌声鼓励下。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>我现在进行A2，\u003c/p>\u003cp>请在一周内找一个，不管是你的伴侣、还是闺蜜、同事都可以，跟他用四步法找出他重点要发展的一个知识领域，并用四步码罗列发展此知识领域的具体方法，将结果发到我们的微信群中。\u003c/p>\u003cp>结语:今天，我们学习知识值多少钱是由哪两个因素决定的呢？独特性和社会需求，以此学习了选择重点发展知识领域的四步法，罗列--&gt;打分--&gt;放入坐标--&gt;排序，最后学习了学习新领域知识的四步法，有哪四步呢？打好基础--&gt;了解行业--&gt;跟进发展--&gt;实践创新，相信大家遵循练习，练习，再练习，这七字真言，定能发展处自己的核心知识力，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}},{"id":3353,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1476982860000,"updated_at":1476984043000,"ria":true},{"id":419,"topic":"如何高效学习","learn_goal":"提高获取知识的效率","remark":"","level":"TF1-1","duration":11,"status":0,"type":0,"chaishujia":{"username":"公子","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"【自我介绍】\r\n大家好，我是今天的拆书家公子，目前是一名互联网产品经理，标签是路痴+learner。\r\n【拆书帮介绍】\r\n喜欢读书的人大多会遇到一个问题，书买了很多却读不完，读了很多书却好像并不能过得更好。拆书就可以很好解决这个问题。\r\n拆书 是一种学习方法论，源于赵周老师《这样读书就够了》，利用便签法让人读一本书能达到同主题培训的效果，把书中的内容通过拆书家引导，促进，拆为己用的过程。\r\n拆书帮则是基于拆书法上的的学习爱好者社群。","ratings_count":0,"texts":[{"id":948,"quote":"人不是为了学知识而活着，所以我们的一生一定要去寻找更多的快乐：要锻炼身体，要去游泳、打球、K歌。在这里笔者只是从知识获取的角度说，在时间固定的情况下，要学会判断知识学习方式的价值，就是说要提高“价值/时间”的职，在年轻的时候总觉得有大把的青春，可你纵有一天会感觉到时间对自己很吝啬，时间如此短暂，所以要考虑如何更有效率的去获取知识。","explains":"4象限的定律一般用于平常任务管理和项目管理中，这边做了一个很好的转化，就像上面提到的，比较难以理解的是两点。\r\n第1象限，所花的时间和获取的价值都比较高，比如，你只是为了考证（你已经有这样的工作经验，但为了升职加薪等），你可以看看有没有其他办法花费时间短但同等价值，例如选择参加专门的辅导班等方案。花费时间短但是价值低的需要斟酌怎么理解呢，虽然时间短，但毕竟是投入了时间，价值不高很多时候可以考虑放弃。但是如果是为了开拓一个新领域，或者感觉这个内容价值不大，但是可以认识很多新的人，精力充足也可以了解。\r\n关于价值没有确切的定义，可以是能帮你赚钱，能让你有愉悦感，能让你获得成就感等方面。能够对你精神或生活产生正向帮助的内容。","interaction":"微信上冒了很多微课，最开始参加了很多，例如理财课，摄影，阅读等等，但是因为盲目参加再加上时间并不是每个都参加，上个月报名参加了职场充电宝的摄影课程，一个因为免费嘛，就报了，还有就是自己手机摄像比较糟糕，但实际上我对于摄影没有很多爱好，这个是一个系列的，除了第一课听了大部分后后面就没有继续，听了个细枝末节去实践，本来拍照就挺烂的，实践后更烂了。\r\n【A1】这个就是我第4象限中的花费时间短，价值不高（我不爱好，没有心理上满足，学了皮毛，拍得更烂，没有成就感，那么烂的技术更不可能有物质上的收获）。\r\n【A2】打开一个空白word/excel文档，写下你正在学习和想要学习的技能/知识清单，并按掌握技能需要的时间和价值填入以上对应象限，以我要学习的技能为例：\r\n注意：对于技能的时间—价值并不是永恒不变的，应该根据当前的需要而制定。\r\n这里，我选择的是三个月为1个技能学习周期，里面的耗费时间长短衡量也是以三个月为尺度。价值可以有不同的定义，例如经济上（能上你升职加薪、赚钱）、精神上（是你的爱好，学习过程让你产生愉悦感）、个人满足（让你有成就感）等等。\r\n另外，虽然现在的职场要求我们只学一门不大现实，但是同时学习的技能最好不要超过3个。长期投资的技能在当前3个重点投资技能学习完成了，或者特殊情况再去学习哦。","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1464752503000,"updated_at":1464752530000,"ria":true},{"id":319,"topic":"一个小方法，让你更加了解自己","learn_goal":"了解自己真正的优势","remark":"你真的了解自己吗？你知道自己的优势在哪里吗？你眼中的自己和别人眼中的你是否是同一个人呢？\r\n一个小方法，就可以让你知道在别人眼中，自己真正的优势是什么。","level":"TF1-2","duration":15,"status":0,"type":0,"chaishujia":{"username":"郭彦超","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好，我是超超，今天我要分享的主题是：一个小方法，让你更加了解自己。本次分享的片段来自于《你的知识需要管理》这本书。这本书是知识管理专家田志刚老师针对知识管理入门所写的，主要介绍了个人知识管理的方法。在我们的日常工作和学习中，都离不开对信息和知识的处理，而现在又是信息和知识爆炸的时代，如何才能提高自己处理信息和知识的能力？如何才能更好地学习而不至于落伍？这本书都会给你答案。","ratings_count":0,"texts":[{"id":846,"quote":"确定你的学习方向之了解自己\r\n 如何确定自己学习知识的方向，根本就在于了解你自己，在确定目标的情况下发挥自己的优势。有一个方法可以让你了解自己，就是让熟悉你的人告诉你，他们感觉到的你的个人优势是什么，我们称之为“求求你，表扬我”。\r\n 在心理学上讲，你眼中的自己和别人眼中的自己是不同的，而从人的社会性角度而言，可能别人眼中的你才是真正的自己，他们可能更能清楚你的优势。\r\n 方法是选择10个最熟悉你的人，包括你的家庭成员、朋友、工作同事、上司、老师等，然后征求他们对你的认识。记住，这里征求的是在他们眼中你最优秀的部分，而不是对你的意见和建议，不是你的不足。上面已经讲到过，要成功，需要发挥你的优势而不是去补你的劣势，所以你征求的是在他们心中觉得你最优秀的地方在哪里。在做这个工作的时候，你除了要求他们说出你的优秀外，还要要求他们用例子来证明他们的观点。\r\n 如果你去做，你就会发现结果跟你心目中的自己不同，你会发现自己原来还有这么多的优势。\r\n步骤：\r\n1、选择10个最熟悉你的人；\r\n2、写下自己寻求别人表扬的文本并标注好完成时间；\r\n3、通过微信/短信/邮件发送给选定的对象；\r\n4、收集反馈，发现未知的自己。","explains":"我知道来拆书帮的小伙伴都是爱学习爱成长的小伙伴，不知道有没有小伙伴会有类似这样的困扰：我想学习，我想提高自己，但我不知道自己喜欢什么？又或者我想找到自己努力的方向，可是我不知道怎样才能找到它。之所以有这样的困扰，或多或少是对自己的了解不够。或许了解自己才是确定学习方向的第一步。\r\n这个片段告诉了我们一个非常简单但十分有效的了解自己的方法，那就是让熟悉你的人来表扬你。很多时候我们以为的自己与别人以为的我们并不一样，从别人的视角来看自己，才能对自己有更深的了解。拿我自己来说，之前我一直认为自己是一个内向的人，之所以这么认为主要是自己在众人面前不太擅长表达自己，有了想法也不敢去说，害怕说错；又或者在很热闹的聚会中我常常不想说话，不知道要和别人聊些什么。后来，当我一遍遍听到别人评价我外向时，我很困惑，难道我不是内向的宝宝吗？所以当我告诉他们我明明很内向好么，我的小伙伴们都惊呆了，因为在他们看来，我根本不内向，没有人比我还能说了，甚至有一个朋友因为我平时喜欢吵吵，而叫我“吵吵”。所以我才恍然大悟，原来我是外向的人啊，而之后通过进一步分析我才知道之所以在人前不敢表达自己的想法是自信心不足，而之所以在聚会上不想说话，觉得孤独，纯粹是90后那抹淡淡的忧伤在作怪，不止我忧伤，很多人都忧伤。自从知道我是个外向的人之后，我有意识地确定了自己的一个学习方向，因为活泼外向时我的优势，我喜欢和别人交流，所以我更加注重沟通和表达的学习，我喜欢听我的师父懿琳拆书，也会积极完成师父布置的作业。之所以努力的做这些，就是为了锻炼自己的沟通和表达能力。","interaction":"A1：这是我自己在受到别人表扬之后确定学习方向的案例。那么现在大家分小组，回顾一下，在之前的经历中，有没有人对你的夸奖让你对自己有了新的认识呢？比如在他夸奖了你之后，你发现原来自己还有这方面的技能，又或者原来我比想象中更有能力？请大家在小组内分享下。\r\nA2：所以说呢，有的时候我们对自己的定义跟别人对我们的评价好像是有差别的。现在大家翻到片段的背面，我给出了一个模板，大家看过模板之后想一下自己请求别人表扬你时应该怎么组织属于自己的语言呢？然后在下面的答题框里写下以下几个要点，1、你打算什么时间请朋友来夸你呢；2、你打算请哪些朋友来夸夸你呢；3、你请他们夸你的时候你打算怎么组织语言呢？给大家5min的时间。\r\n好了，在你写好怎样让别人表扬你的文本之后，就可以发送给选定的对象，让他们来夸夸你，相信你会在别人眼中看到不一样的自己。希望大家使用这个方法都能更多地了解自己，发现自己的优势，确定自己的学习方向，让自己在提高自我的路上越走越远。谢谢大家！","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1462805489000,"updated_at":1462805489000,"ria":true}]};